	function automatic [3:0] ascii_to_num;
	input logic
		[7:0]		ascii;
	return (((ascii >= 8'h30) && (ascii <= 8'h39)) ? 4'((ascii - 8'h30)) : 
		4'(((ascii - 8'h41) + 10)));
	endfunction

	function automatic ascii_to_num_err;
	input logic
		[7:0]		ascii;
	return (((ascii >= 8'h30) && (ascii <= 8'h39)) ? 1'b0 : (((ascii >= 
		8'h41) && (ascii <= 8'h46)) ? 1'b0 : 1'b1));
	endfunction

	function automatic [7:0] num_to_ascii;
	input logic
		[3:0]		num_in_hex;
	return ((num_in_hex <= 9) ? (8'(num_in_hex) + 8'h30) : ((8'(num_in_hex) 
		+ 8'h41) - 8'd10));
	endfunction
