	function automatic axi_inner_is_dev;
	input logic
		[3:0]		inner;
	axi_inner_is_dev = ((inner == 4'b0) | (inner == 4'b1));
	endfunction

	function automatic axi_inner_is_nrm;
	input logic
		[3:0]		inner;
	axi_inner_is_nrm = (~axi_inner_is_dev(inner));
	endfunction

	function automatic axi_inner_is_ch;
	input logic
		[3:0]		inner;
	axi_inner_is_ch = (~(((inner == 4'b0) | (inner == 4'b1)) | (inner ==
		4'b0011)));
	endfunction

	function automatic axi_inner_is_nc;
	input logic
		[3:0]		inner;
	axi_inner_is_nc = (axi_inner_is_nrm(inner) & (~axi_inner_is_ch(inner)));
	endfunction

	function automatic eventbus_t format_eventbus;
	input pmu_events_t	evts;
	format_eventbus = eventbus_t'({evts.pf_buffer_hit, evts.pf_buffer_miss,
		evts.pf_buffer_full, evts.pf_lf_la_6, evts.pf_lf_la_5,
		evts.pf_lf_la_4, evts.pf_lf_la_3, evts.pf_lf_la_2,
		evts.pf_lf_la_1, evts.cde_stall_other, evts.cde_stall_custom,
		evts.cde_stall_dependency, evts.cde_stall_resource,
		evts.cde_stall, evts.cde_pred, evts.cde_vcx3_vec_inst_retired,
