	function automatic [2:0] num_to_pmu_event3;
	input logic
		[1:0]		num_i;
	num_to_pmu_event3 = ((num_i == 2'b11) ? 3'b100 : ((num_i == 2'b10) ?
		3'b010 : ((num_i == 2'b1) ? 3'b1 : 3'b0)));
	endfunction

	function automatic [23:12] tcm_mask;
	input logic
		[3:0]		tcm_sz;

	reg	[23:12]		mask;
	begin
	  case (tcm_sz)
	    4'b0011:
	      mask = 12'b111111111111;
	    4'b0100:
	      mask = 12'b111111111110;
	    4'b0101:
	      mask = 12'b111111111100;
	    4'b0110:
	      mask = 12'b111111111000;
	    4'b0111:
	      mask = 12'b111111110000;
	    4'b1000:
	      mask = 12'b111111100000;
	    4'b1001:
	      mask = 12'b111111000000;
	    4'b1010:
	      mask = 12'b111110000000;
	    4'b1011:
	      mask = 12'b111100000000;
	    4'b1100:
	      mask = 12'b111000000000;
	    4'b1101:
	      mask = 12'b110000000000;
	    4'b1110:
	      mask = 12'b100000000000;
	    4'b1111:
	      mask = 12'b0;
	    4'b0, 4'b1, 4'b0010:
	      mask = 12'b0;
	    default:
	      mask = 12'bxxxxxxxxxxxx;
	  endcase
	  tcm_mask = mask;
	end
	endfunction

	function automatic [2:0] ahb_mask;
	input logic
		[2:0]		ahbp_sz;

	reg	[2:0]		mask;
	begin
	  case (ahbp_sz)
	    3'b1:
	      mask = 3'b111;
	    3'b010:
	      mask = 3'b110;
	    3'b011:
	      mask = 3'b100;
	    3'b100:
	      mask = 3'b0;
	    3'b101, 3'b110, 3'b111:
	      mask = 3'b0;
	    3'b0:
	      mask = 3'b0;
	    default:
	      mask = 3'bxxx;
	  endcase
	  ahb_mask = mask;
	end
	endfunction

	function automatic mem_tgt_t gen_mem_tgt;
	input logic
		[31:0]		addr;
	input idtcmcr_t		itcmcr;
	input idtcmcr_t		dtcmcr;
	input ahbpcr_t		ahbpcr;

	logic			itcm_sz0;
	logic			dtcm_sz0;
	logic			ahbp_sz0;
	logic	[23:12]		itcm_mask;
	logic	[23:12]		dtcm_mask;
	logic	[28:26]		ahbp_mask;
	mem_tgt_t		mem_tgt;
	begin
	  itcm_sz0 = ((~itcmcr.en) | (itcmcr.sz == 4'b0));
	  dtcm_sz0 = ((~dtcmcr.en) | (dtcmcr.sz == 4'b0));
	  ahbp_sz0 = ((~ahbpcr.en) | (ahbpcr.sz == 3'b0));
	  itcm_mask = tcm_mask(itcmcr.sz);
	  dtcm_mask = tcm_mask(dtcmcr.sz);
	  ahbp_mask = ahb_mask(ahbpcr.sz);
	  case (addr[31:29]) inside 
	    3'b0:
	      if ((itcm_sz0 || (|addr[28:24])) || (|(addr[23:12] & 
		      itcm_mask[23:12]))) begin
		mem_tgt = yamin_pkg::AXI;
	      end
	      else begin
		mem_tgt = yamin_pkg::ITCM;
	      end
	    3'b1:
	      if ((dtcm_sz0 || (|addr[28:24])) || (|(addr[23:12] & 
		      dtcm_mask[23:12]))) begin
		mem_tgt = yamin_pkg::AXI;
	      end
	      else begin
		mem_tgt = yamin_pkg::DTCM;
	      end
	    3'b010:
	      if (ahbp_sz0 || (|(addr[28:26] & ahbp_mask))) begin
		mem_tgt = yamin_pkg::AXI;
	      end
	      else begin
		mem_tgt = yamin_pkg::PIU;
	      end
	    3'b011, 3'b100, 3'b101, 3'b110:
	      mem_tgt = yamin_pkg::AXI;
	    3'b111:
	      mem_tgt = yamin_pkg::PIU;
	    default:
	      mem_tgt = mem_tgt_t'('x);
	  endcase
	  gen_mem_tgt = mem_tgt;
	end
	endfunction

	function automatic p_mem_tgt_t gen_p_mem_tgt;
	input logic
		[31:0]		addr;
	return ((~addr[31]) ? yamin_pkg::PAHB : ((|addr[28:20]) ? 
		yamin_pkg::PAHB : ((~(|addr[19:18])) ? yamin_pkg::IPPB : 
		yamin_pkg::EPPB)));
	endfunction

	function automatic attrs_are_dev;
	input attr_t		attr;
	return (attr.outer == yamin_pkg::DEV);
	endfunction

	function automatic attrs_are_nrm;
	input attr_t		attr;
	return (attr.outer != yamin_pkg::DEV);
	endfunction

	function automatic attrs_are_nc;
	input attr_t		attr;
	return ((attr.outer != yamin_pkg::DEV) & ((attr.inner == yamin_pkg::NC) 
		| (attr.inner == yamin_pkg::DEV)));
	endfunction

	function automatic attrs_are_ch;
	input attr_t		attr;
	return (((attr.outer != yamin_pkg::DEV) & (attr.inner != yamin_pkg::NC))
		& (attr.inner != yamin_pkg::DEV));
	endfunction

	function automatic half_attrs_are_wb_wa;
	input half_attr_t	attr;
	return ((((attr == yamin_pkg::WB_WA) | (attr == yamin_pkg::WB_WA_T)) | (
		attr == yamin_pkg::WB_RWA)) | (attr == yamin_pkg::WB_RWA_T));
	endfunction

	function automatic half_attrs_are_wb_not_wa;
	input half_attr_t	attr;
	return (((attr == yamin_pkg::WB) | (attr == yamin_pkg::WB_RA)) | (attr 
		== yamin_pkg::WB_RA_T));
	endfunction

	function automatic half_attrs_are_wt_wa;
	input half_attr_t	attr;
	return ((((attr == yamin_pkg::WT_WA) | (attr == yamin_pkg::WT_WA_T)) | (
		attr == yamin_pkg::WT_RWA)) | (attr == yamin_pkg::WT_RWA_T));
	endfunction

	function automatic half_attrs_are_wt_not_wa;
	input half_attr_t	attr;
	return (((attr == yamin_pkg::WT) | (attr == yamin_pkg::WT_RA)) | (attr 
		== yamin_pkg::WT_RA_T));
	endfunction

	function automatic attrs_are_wt;
	input attr_t		attr;
	return ((attr.outer != yamin_pkg::DEV) & (half_attrs_are_wt_wa(
		attr.inner) | half_attrs_are_wt_not_wa(attr.inner)));
	endfunction

	function automatic attrs_are_wb;
	input attr_t		attr;
	return ((attr.outer != yamin_pkg::DEV) & (half_attrs_are_wb_wa(
		attr.inner) | half_attrs_are_wb_not_wa(attr.inner)));
	endfunction

	function automatic attrs_are_wa;
	input attr_t		attr;
	return attr.inner[0];
	endfunction

	function automatic attrs_are_ra;
	input attr_t		attr;
	return attr.inner[1];
	endfunction

	function automatic attrs_are_transient;
	input attr_t		attr;
	return (~attr.inner[3]);
	endfunction

	function automatic attrs_are_shareable;
	input attr_t		attr;
	return (attr.shareable != yamin_pkg::NON_SHARE);
	endfunction

	function automatic outer_attrs_are_ch;
	input attr_t		attr;
	return ((attr.outer != yamin_pkg::NC) & (attr.outer != yamin_pkg::DEV));
	endfunction

	function automatic outer_attrs_are_wa;
	input attr_t		attr;
	return attr.outer[0];
	endfunction

	function automatic outer_attrs_are_ra;
	input attr_t		attr;
	return attr.outer[1];
	endfunction

	function automatic outer_attrs_are_wb;
	input attr_t		attr;
	return (half_attrs_are_wb_wa(attr.outer) | half_attrs_are_wb_not_wa(
		attr.outer));
	endfunction

	function automatic outer_attrs_are_wt;
	input attr_t		attr;
	return (half_attrs_are_wt_wa(attr.outer) | half_attrs_are_wt_not_wa(
		attr.outer));
	endfunction

	function automatic attr_t munge_dside_attrs;
	input attr_t		attrs;
	input logic		ccr_dc;
	input mscr_t		mscr;
	input logic		dc_inaccessible;
	input logic		mve;
	input logic		dbg;
	begin
	  munge_dside_attrs.shareable = ((~attrs_are_ch(attrs)) ?
		  yamin_pkg::SHAREABLE : attrs.shareable);
	  munge_dside_attrs.outer = attrs.outer;
	  munge_dside_attrs.inner = attrs.inner;
	  if (attrs_are_dev(attrs) & mve) begin
	    munge_dside_attrs.inner = half_attr_t'(4'b1100);
	  end
	  else if (attrs_are_ch(attrs)) begin
	    if (mscr.forcewt) begin
	      munge_dside_attrs.inner = half_attr_t'((munge_dside_attrs.inner &
		      4'b1011));
	    end
	    if (attrs_are_shareable(attrs)) begin
	      munge_dside_attrs.inner = yamin_pkg::NC;
	    end
	    else if ((((~ccr_dc) | (~mscr.dcactive)) | dc_inaccessible) | dbg) 
		    begin
	      munge_dside_attrs.inner = half_attr_t'({1'b1,
		      munge_dside_attrs.inner[2], 2'b0});
	    end
	  end
	end
	endfunction

	function automatic battr_t mem_attrs_to_battrs;
	input attr_t		attrs;

	logic			are_ch;
	logic			are_nc;
	logic			are_dev;
	begin
	  are_dev = (attrs.outer == yamin_pkg::DEV);
	  are_nc = ((~are_dev) & (((attrs.inner == yamin_pkg::NC) | (attrs.inner
		  == yamin_pkg::DEV)) | attrs_are_shareable(attrs)));
	  are_ch = ((~are_dev) & (~are_nc));
	  mem_attrs_to_battrs.are_ch = are_ch;
	  mem_attrs_to_battrs.are_nc = are_nc;
	  mem_attrs_to_battrs.are_dev = are_dev;
	end
	endfunction

