	function automatic [6:0] attrs_to_hprot;
	input logic		priv;
	input attr_t		attrs;
	input logic		rnw;

	logic	[6:0]		hprot;
	begin
	  hprot[0] = 1'b1;
	  hprot[1] = priv;
	  hprot[2] = ((attrs_are_dev(attrs) & (|attrs[3:2])) |
		  outer_attrs_are_wb(attrs));
	  hprot[3] = (~attrs_are_dev(attrs));
	  hprot[4] = outer_attrs_are_ch(attrs);
	  hprot[5] = (outer_attrs_are_ch(attrs) & (rnw ?
		  outer_attrs_are_ra(attrs) : outer_attrs_are_wa(attrs)));
	  hprot[6] = ((~attrs_are_dev(attrs)) & attrs_are_shareable(attrs));
	  attrs_to_hprot = hprot;
	end
	endfunction

	function automatic attr_t hprot_to_attrs;
	input logic
		[6:0]		hprot;

	attr_t			attr;
	begin
	  case ({hprot[6], hprot[5], hprot[4], hprot[3], hprot[2]}) inside 
	    5'b0:
	      attr = {yamin_pkg::SHAREABLE, yamin_pkg::DEV, half_attr_t'(4'b0)};
	    5'b1:
	      attr = {yamin_pkg::SHAREABLE, yamin_pkg::DEV,
		      half_attr_t'(4'b1000)};
	    5'b00010:
	      attr = {yamin_pkg::NON_SHARE, yamin_pkg::NC, yamin_pkg::NC};
	    5'b0z110:
	      attr = {yamin_pkg::NON_SHARE, yamin_pkg::WT, yamin_pkg::WT};
	    5'b0z111:
	      attr = {yamin_pkg::NON_SHARE, yamin_pkg::WB, yamin_pkg::WB};
	    5'b10010:
	      attr = {yamin_pkg::SHAREABLE, yamin_pkg::NC, yamin_pkg::NC};
	    5'b1z110:
	      attr = {yamin_pkg::SHAREABLE, yamin_pkg::WT, yamin_pkg::WT};
	    5'b1z111:
	      attr = {yamin_pkg::SHAREABLE, yamin_pkg::WB, yamin_pkg::WB};
	    default:
	      attr = attr_t'('x);
	  endcase
	  hprot_to_attrs = attr;
	end
	endfunction

	function automatic [2:0] attrs_to_pprot;
	input logic		priv;
	input logic		ns_attr;

	logic	[2:0]		pprot;
	begin
	  pprot[0] = priv;
	  pprot[1] = ns_attr;
	  pprot[2] = 1'b0;
	  attrs_to_pprot = pprot;
	end
	endfunction

	function automatic dc_status_t create_dc_status;
	input logic		dirty;
	input logic		transient;
	input half_attr_t	outer_attrs;
	create_dc_status = (((~dirty) & transient) ? yamin_pkg::DCSTATUS_CLEAN_T
		: (((~dirty) & (~transient)) ? yamin_pkg::DCSTATUS_CLEAN_NT :
		((dirty & half_attrs_are_wb_wa(outer_attrs)) ?
		yamin_pkg::DCSTATUS_DIRTY_WB_WA : ((dirty &
		half_attrs_are_wb_not_wa(outer_attrs)) ?
		yamin_pkg::DCSTATUS_DIRTY_WB : ((dirty &
		half_attrs_are_wt_wa(outer_attrs)) ?
		yamin_pkg::DCSTATUS_DIRTY_WT_WA : ((dirty &
		half_attrs_are_wt_not_wa(outer_attrs)) ?
		yamin_pkg::DCSTATUS_DIRTY_WT :
		yamin_pkg::DCSTATUS_DIRTY_NC))))));
	endfunction

	function automatic dc_status_is_clean;
	input dc_status_t	status;
	dc_status_is_clean = ((status == yamin_pkg::DCSTATUS_CLEAN_T) | (status
		== yamin_pkg::DCSTATUS_CLEAN_NT));
	endfunction

	function automatic dc_status_is_transient;
	input dc_status_t	status;
	dc_status_is_transient = (status == yamin_pkg::DCSTATUS_CLEAN_T);
	endfunction

	function automatic half_attr_t dc_status_outer_attrs;
	input dc_status_t	status;
	dc_status_outer_attrs = ((status == yamin_pkg::DCSTATUS_DIRTY_WB_WA) ?
		yamin_pkg::WB_WA : ((status == yamin_pkg::DCSTATUS_DIRTY_WB) ?
		yamin_pkg::WB : ((status == yamin_pkg::DCSTATUS_DIRTY_WT_WA) ?
		yamin_pkg::WT_WA : ((status == yamin_pkg::DCSTATUS_DIRTY_WT) ?
		yamin_pkg::WT : yamin_pkg::NC))));
	endfunction
endpackage

