	function automatic [31:0] pad_fpscr;
	input fpscr_t		raw_fpscr;
	pad_fpscr = {raw_fpscr.nzcv, raw_fpscr.qc, raw_fpscr.ahp, raw_fpscr.dn,
		raw_fpscr.fz, raw_fpscr.rmode, {2 {1'b0}}, raw_fpscr.fz16,
		raw_fpscr.ltpsize, {8 {1'b0}}, raw_fpscr.fp_exc[5], {2 {1'b0}},
		raw_fpscr.fp_exc[4:0]};
	endfunction

	function automatic [31:0] pad_vpr;
	input vpr_t		raw_vpr;
	pad_vpr = {{8 {1'b0}}, raw_vpr};
	endfunction

	function automatic sy_wr_fpscr_nzcvqc;
	input sy_op_t		op;
	case (op.ctl.info.tgt)
	  yamin_epu_pkg::SY_TGT_NONE, yamin_epu_pkg::SY_TGT_VPR, 
		  yamin_epu_pkg::SY_TGT_VPR_P0:
	    sy_wr_fpscr_nzcvqc = 1'b0;
	  yamin_epu_pkg::SY_TGT_FPSCR, yamin_epu_pkg::SY_TGT_FPSCR_CXT_NS, 
		  yamin_epu_pkg::SY_TGT_FPSCR_CXT_S, 
		  yamin_epu_pkg::SY_TGT_FPSCR_NZCVQC, 
		  yamin_epu_pkg::SY_TGT_FPSCR_VPR:
	    sy_wr_fpscr_nzcvqc = 1'b1;
	  default:
	    sy_wr_fpscr_nzcvqc = 'x;
	endcase
	endfunction

