	function automatic clz_2_t clz_2;
	input logic
		[1:0]		op;
	begin
	  clz_2.valid = (|op);
	  clz_2.position = (~op[1]);
	end
	endfunction

	function automatic clz_4_t clz_4;
	input logic
		[3:0]		op;

	clz_2_t			vp_0;
	clz_2_t			vp_1;
	begin
	  vp_0 = clz_2(op[1:0]);
	  vp_1 = clz_2(op[3:2]);
	  clz_4.valid = (vp_0.valid | vp_1.valid);
	  clz_4.position[1] = (~vp_1.valid);
	  clz_4.position[0] = (vp_1.valid ? vp_1.position : vp_0.position);
	end
	endfunction

	function automatic clz_8_t clz_8;
	input logic
		[7:0]		op;

	clz_4_t			vp_0;
	clz_4_t			vp_1;
	begin
	  vp_0 = clz_4(op[3:0]);
	  vp_1 = clz_4(op[7:4]);
	  clz_8.valid = (vp_0.valid | vp_1.valid);
	  clz_8.position[2] = (~vp_1.valid);
	  clz_8.position[1:0] = (vp_1.valid ? vp_1.position : vp_0.position);
	end
	endfunction

	function automatic clz_16_t clz_16;
	input clz_8_t		vp_0;
	input clz_8_t		vp_1;
	begin
	  clz_16.valid = (vp_0.valid | vp_1.valid);
	  clz_16.position[3] = (~vp_1.valid);
	  clz_16.position[2:0] = (vp_1.valid ? vp_1.position : vp_0.position);
	end
	endfunction

	function automatic clz_32_t clz_32;
	input clz_16_t		vp_0;
	input clz_16_t		vp_1;
	begin
	  clz_32.valid = (vp_0.valid | vp_1.valid);
	  clz_32.position[4] = (~vp_1.valid);
	  clz_32.position[3:0] = (vp_1.valid ? vp_1.position : vp_0.position);
	end
	endfunction

	function automatic [7:0] select_sign;
	input logic
		[63:0]		select_sign_in;
	input sz_t		select_sign_sz;
	begin

	  integer		i;
	  for (i = 0; (i < 8); i += 1)
	    case (select_sign_sz)
	      yamin_epu_pkg::SZ_8:
		select_sign[i] = select_sign_in[((8 * i) + 7)];
	      yamin_epu_pkg::SZ_16:
		select_sign[i] = select_sign_in[((16 * (i / 2)) + 15)];
	      yamin_epu_pkg::SZ_32:
		select_sign[i] = select_sign_in[((32 * (i / 4)) + 31)];
	      default:
		select_sign[i] = 'x;
	    endcase
	end
	endfunction

	function automatic [63:0] create_mask8;
	input logic
		[7:0]		a;
	create_mask8 = {{8 {a[7]}}, {8 {a[6]}}, {8 {a[5]}}, {8 {a[4]}}, {8
		{a[3]}}, {8 {a[2]}}, {8 {a[1]}}, {8 {a[0]}}};
	endfunction

	function automatic logic [63:0] csa_sum;
	input logic
		[63:0]		pp0;
	input logic
		[63:0]		pp1;
	input logic
		[63:0]		pp2;
	csa_sum = ((pp0 ^ pp1) ^ pp2);
	endfunction

