	function automatic logic [63:0] csa_carry;
	input logic
		[63:0]		pp0;
	input logic
		[63:0]		pp1;
	input logic
		[63:0]		pp2;
	csa_carry = {(((pp0[62:0] & pp1[62:0]) | (pp1[62:0] & pp2[62:0])) |
		(pp2[62:0] & pp0[62:0])), 1'b0};
	endfunction

