	function automatic itstate_t itadv1;
	input itstate_t		itstate;
	begin
	  itadv1.cond = ({itstate.cond[3:1], itstate.mask[3]} & {4
		  {(|itstate.mask[2:0])}});
	  itadv1.mask = {itstate.mask[2:0], 1'b0};
	end
	endfunction

	function automatic itstate_t itadv2;
	input itstate_t		itstate;
	begin
	  itadv2.cond = ({itstate.cond[3:1], itstate.mask[2]} & {4
		  {(|itstate.mask[1:0])}});
	  itadv2.mask = {itstate.mask[1:0], 2'b0};
	end
	endfunction

	function automatic itstate_t itadv;
	input logic		i0_valid;
	input logic		i1_valid;
	input logic		i0_yngr;
	input logic		i0_it;
	input logic		i1_it;
	input logic		i01_br;
	input itstate_t		i0_itstate;
	input itstate_t		i1_itstate;
	input itstate_t		itstate;

	itstate_t		itadv0;
	itstate_t[1:0]		itadv1_nbr;
	itstate_t[1:0]		itadv1;
	itstate_t		itadv2_nbr;
	itstate_t		itadv2;
	begin
	  itadv0 = itstate;
	  itadv1_nbr[0] = (i0_it ? i0_itstate : '{cond:{itstate.cond[3:1],
		  itstate.mask[3]}, mask:{itstate.mask[2:0], 1'b0}});
	  itadv1_nbr[1] = (i1_it ? i1_itstate : '{cond:{itstate.cond[3:1],
		  itstate.mask[3]}, mask:{itstate.mask[2:0], 1'b0}});
	  itadv1[0].cond = ((i01_br | (~|itadv1_nbr[0].mask)) ? '0 :
		  itadv1_nbr[0].cond);
	  itadv1[0].mask = (i01_br ? '0 : itadv1_nbr[0].mask);
	  itadv1[1].cond = ((i01_br | (~|itadv1_nbr[1].mask)) ? '0 :
		  itadv1_nbr[1].cond);
	  itadv1[1].mask = (i01_br ? '0 : itadv1_nbr[1].mask);
	  case ({i0_yngr, i0_it, i1_it}) inside 
	    3'b0z1:
	      itadv2_nbr = i1_itstate;
	    3'b01z:
	      itadv2_nbr = '{cond:{i0_itstate.cond[3:1], i0_itstate.mask[3]},
		      mask:{i0_itstate.mask[2:0], 1'b0}};
	    3'b1z1:
	      itadv2_nbr = '{cond:{i1_itstate.cond[3:1], i1_itstate.mask[3]},
		      mask:{i1_itstate.mask[2:0], 1'b0}};
	    3'b11z:
	      itadv2_nbr = i0_itstate;
	    3'bz00:
	      itadv2_nbr = '{cond:{itstate.cond[3:1], itstate.mask[2]},
		      mask:{itstate.mask[1:0], 2'b0}};
	    default:
	      itadv2_nbr = 'x;
	  endcase
	  itadv2.cond = ((i01_br | (~|itadv2_nbr.mask)) ? '0 : itadv2_nbr.cond);
	  itadv2.mask = (i01_br ? '0 : itadv2_nbr.mask);
	  case ({i1_valid, i0_valid})
	    2'b0:
	      itadv = itadv0;
	    2'b1:
	      itadv = itadv1[0];
	    2'b10:
	      itadv = itadv1[1];
	    2'b11:
	      itadv = itadv2;
	    default:
	      itadv = 'x;
	  endcase
	end
	endfunction

