	begin

	  logic	[4:0]		sysm_comp;
	  sysm_comp = (((((({SPEC_REG_W {(sysm[7:3] == 5'b0)}} & ((({SPEC_REG_W
		  {((~sysm[2]) & (~sysm[0]))}} & yamin_core_pkg::SPEC_REG_APSR)
		  | ({SPEC_REG_W {(sysm[2] & sysm[0])}} &
		  yamin_core_pkg::SPEC_REG_IPSR)) | ({SPEC_REG_W {((~sysm[2]) &
		  sysm[0])}} & yamin_core_pkg::SPEC_REG_XPSR))) | ({SPEC_REG_W
		  {(sysm[7:3] == 5'b1)}} & (((({SPEC_REG_W {(sysm[2:0] ==
		  3'b0)}} & yamin_core_pkg::SPEC_REG_MSP) | ({SPEC_REG_W
		  {(sysm[2:0] == 3'b1)}} & yamin_core_pkg::SPEC_REG_PSP)) |
		  ({SPEC_REG_W {(sysm[2:0] == 3'b010)}} &
		  yamin_core_pkg::SPEC_REG_MSPLIM)) | ({SPEC_REG_W {(sysm[2:0]
		  == 3'b011)}} & yamin_core_pkg::SPEC_REG_PSPLIM)))) |
		  ({SPEC_REG_W {(sysm[7:3] == 5'b10001)}} & (((({SPEC_REG_W
		  {(sysm[2:0] == 3'b0)}} & yamin_core_pkg::SPEC_REG_MSP_NS) |
		  ({SPEC_REG_W {(sysm[2:0] == 3'b1)}} &
		  yamin_core_pkg::SPEC_REG_PSP_NS)) | ({SPEC_REG_W {(sysm[2:0]
		  == 3'b010)}} & yamin_core_pkg::SPEC_REG_MSPLIM_NS)) |
		  ({SPEC_REG_W {(sysm[2:0] == 3'b011)}} &
		  yamin_core_pkg::SPEC_REG_PSPLIM_NS)))) | ({SPEC_REG_W
		  {(sysm[7:3] == 5'b00010)}} & ((((({SPEC_REG_W {(sysm[2:0] ==
		  3'b0)}} & yamin_core_pkg::SPEC_REG_PRIMASK) | ({SPEC_REG_W
