/* Source file "../../logical/models/generic/syncff_set.sv", line 4 */
`timescale 1 ns / 1 ps
module syncff_set(clock, reset_n, data_i, data_o);
	input			clock;

	logic			clock;
	input			reset_n;
	logic			reset_n;
	input			data_i;
	logic			data_i;
	output			data_o;
	logic			data_o;
	logic			sync_p1;
	logic			sync_p2;

	assign data_o = sync_p2;

	always @(posedge clock or negedge reset_n) begin
	  if (!reset_n) begin
	    sync_p1 <= 1'b1;
	    sync_p2 <= 1'b1;
	  end
	  else
	    begin
	      sync_p1 <= data_i;
	      sync_p2 <= sync_p1;
	    end
	end
endmodule
`endcelldefine

