module nic400_cdc_capt_sync_1(clk, resetn, d_async, sync_en, q);
	parameter		WIDTH		= 4;
	input			clk;
	input			resetn;
	input	[(WIDTH - 1):0]	d_async;
	input			sync_en;

	wire	[(WIDTH - 1):0]	d_noz;
	reg	[(WIDTH - 1):0]	d_sync1;
	output	[(WIDTH - 1):0]	q;
	reg	[(WIDTH - 1):0]	q;

	assign d_noz = d_async;

	always @(posedge clk or negedge resetn) if (!resetn) begin
	  d_sync1 <= {WIDTH {1'b0}};
	  q <= {WIDTH {1'b0}};
	end
	else if (sync_en) begin
	  d_sync1 <= d_noz;
	  q <= d_sync1;
	end
endmodule
