`timescale 1 ns / 1 ps
module yamin_flop_parity_fault_detection(clk, reset_n, flop_next_i, flop_i,
	flop_enable_i, fault_o);
	parameter		WIDTH		= (-1);
	parameter [(WIDTH - 1):0]
				RESET_VALUE	= '0;
	parameter		ID_NAME		= "XXX";
	parameter		ID_NUMBER	= "X";
	parameter		PARITY_CALC_WIDTH
						= 8;
	input			clk;
	input			reset_n;
	input	[(WIDTH - 1):0]	flop_next_i;
	input	[(WIDTH - 1):0]	flop_i;
	input			flop_enable_i;
	output			fault_o;
	localparam		PARITY_GROUPS	= (((WIDTH - 1) / 
		PARITY_CALC_WIDTH) + 1);
	localparam		EXTENDED_WIDTH	= (PARITY_CALC_WIDTH * 
		PARITY_GROUPS);
	localparam		PADDING_WIDTH	= (PARITY_CALC_WIDTH - (WIDTH % 
		PARITY_CALC_WIDTH));
	localparam [(EXTENDED_WIDTH - 1):0]
				RESET_VALUE_PADDED
						= {{PADDING_WIDTH {1'b0}},
		RESET_VALUE};

	wire	[(PARITY_GROUPS - 1):0]
				fault_array;
	wire	[(EXTENDED_WIDTH - 1):0]
				flop_next_padded;
	wire	[(EXTENDED_WIDTH - 1):0]
				flop_padded;
	genvar 			i;

	assign flop_next_padded[(WIDTH - 1):0] = flop_next_i;
	assign flop_padded[(WIDTH - 1):0] = flop_i;
	assign fault_o = (^fault_array);

	if (PADDING_WIDTH != PARITY_CALC_WIDTH) begin : gen_padding 

	  assign flop_next_padded[(EXTENDED_WIDTH - 1):WIDTH] = {PADDING_WIDTH
		  {1'b0}};
	  assign flop_padded[(EXTENDED_WIDTH - 1):WIDTH] = {PADDING_WIDTH
		  {1'b0}};
	end

	for (i = 0; (i < PARITY_GROUPS); i = (i + 1)) begin : gen_parity_flop 
	  localparam		PARITY_RESET_VALUE
						= (^RESET_VALUE_PADDED[(i *
		  PARITY_CALC_WIDTH)+:PARITY_CALC_WIDTH]);

	  wire	[(PARITY_CALC_WIDTH - 1):0]
				flop_group_next = flop_next_padded[(i *
		  PARITY_CALC_WIDTH)+:PARITY_CALC_WIDTH];
	  wire	[(PARITY_CALC_WIDTH - 1):0]
				flop_group = flop_padded[(i *
		  PARITY_CALC_WIDTH)+:PARITY_CALC_WIDTH];
	  wire			flop_group_next_parity = (^flop_group_next);
	  wire			flop_group_parity = (^flop_group);
	  logic			parity_flop;

	  assign fault_array[i] = (parity_flop ^ flop_group_parity);

	  always_ff @(posedge clk or negedge reset_n) begin
	    if (!reset_n) begin
	      parity_flop <= PARITY_RESET_VALUE;
	    end
	    else if (flop_enable_i) begin
	      parity_flop <= flop_group_next_parity;
	    end
	  end
	end
endmodule
