module yamin_cell_semi_sync_flop(clk, reset_n, clk_senable_i, clk_enable_i,
	data_en_i, data_in_i, data_out_o);
	parameter		RESETABLE	= 0;
	parameter		WIDTH		= 1;
	parameter		RAR		= 0;
	input			clk;
	input			reset_n;
	input			clk_senable_i;
	input			clk_enable_i;
	input			data_en_i;
	input	[(WIDTH - 1):0]	data_in_i;
	output	[(WIDTH - 1):0]	data_out_o;

	logic	[(WIDTH - 1):0]	data_out;
	logic			clk_en;
	logic			clk_en_latched;
	logic			clk_gated;

	assign clk_en = ((clk_enable_i & data_en_i) | clk_senable_i);
	assign clk_gated = (clk & clk_en_latched);
	assign data_out_o = data_out;

	always @(*) begin
	  if (~clk) begin
	    clk_en_latched <= clk_en;
	  end
	end

	if ((RESETABLE == 1) || (RAR == 1)) begin : gen_rst 

	  always_ff @(posedge clk_gated or negedge reset_n) if (~reset_n) begin
	    data_out <= {WIDTH {1'b0}};
	  end
	  else begin
	    data_out <= data_in_i;
	  end
	end
	else  begin : gen_non_rst 

	  always_ff @(posedge clk_gated) data_out <= data_in_i;
	end
endmodule
