	reg	[11:0]		OffsetAddr;
	wire	[11:0]		IncrAddr;
	wire	[11:0]		WrapAddr;
	wire	[11:0]		MuxAddr;
	reg	[11:0]		CalcAddr;

	assign IncrAddr = (OffsetAddr + 1'b1);
	assign WrapAddr[11:4] = OffsetAddr[11:4];
	assign WrapAddr[3:0] = ((ALEN & IncrAddr[3:0]) | ((~ALEN) &
		OffsetAddr[3:0]));
	assign MuxAddr = ((ABURST == 2'b10) ? WrapAddr : IncrAddr);
	assign AddrOut = ((ABURST == 2'b0) ? AddrIn : CalcAddr);

	always @(ASIZE or AddrIn) begin : p_OffsetAddrComb
	  case (ASIZE)
	    3'b0:
	      OffsetAddr = AddrIn[11:0];
	    3'b1:
	      OffsetAddr = {1'b0, AddrIn[11:1]};
	    3'b010:
	      OffsetAddr = {2'b0, AddrIn[11:2]};
	    3'b011:
	      OffsetAddr = {3'b0, AddrIn[11:3]};
	    default:
	      OffsetAddr = {12 {1'bx}};
	  endcase
	end
	always @(ASIZE or MuxAddr) begin : p_CalcAddrComb
	  case (ASIZE)
	    3'b0:
	      CalcAddr = MuxAddr;
	    3'b1:
	      CalcAddr = {MuxAddr[10:0], 1'b0};
	    3'b010:
	      CalcAddr = {MuxAddr[9:0], 2'b0};
	    3'b011:
	      CalcAddr = {MuxAddr[8:0], 3'b0};
	    default:
	      CalcAddr = {12 {1'bx}};
	  endcase
	end
endmodule
