	  integer		row;
	  integer		column;
	  for (row = 0; (row < WIDTH); row = (row + 1)) begin
	    for (column = 0; (column < WIDTH); column = (column + 1)) begin
	      if (row < column) begin
		p[row][column] = p_reg[row][column];
	      end
	      else if (row == column) begin
		p[row][column] = 1'b0;
	      end
	      else
		begin
