	      p_en[row][column] = (update_en & (grant_i[row] | grant_i[column]))
		      ;
	    end
	  end
	end
	always @(posedge aclk or negedge aresetn) begin : p_seq_priorities

	  integer		row;
	  integer		column;
	  if (!aresetn) begin
	    for (row = 0; (row < WIDTH); row = (row + 1)) begin
