				highest_qv_value;
	  reg	[(REQUESTS - 1):0]
				highest_mh_i;

	  assign highest_mh = highest_mh_i;
	  assign highest_qos = highest_qv_value;

	  always @(*) begin : p_qv_requests_comb

	    integer		e;
	    integer		qv_level;
	    for (e = 0; (e < REQUESTS); e = (e + 1)) begin
	      for (qv_level = 0; (qv_level < QV_LEVELS); qv_level = (qv_level +
		      1)) begin
		qv_requests[qv_level][e] = (request_valids[e] &
			(request_qos[(QOS_WIDTH * e)+:QOS_WIDTH] >= qv_level));
	      end
	    end
	  end
	  always @(*) begin : p_is_qv_comb

	    integer		qv_level;
	    for (qv_level = 0; (qv_level < QV_LEVELS); qv_level = (qv_level + 1)
		    ) begin
	      is_qv[qv_level] = (|qv_requests[qv_level]);
	    end
	  end
	  always @(*) begin : p_entry_cmp_value_comb

	    integer		qv_level;
	    highest_qv_value = {QOS_WIDTH {1'b0}};
	    for (qv_level = 0; (qv_level < QV_LEVELS); qv_level = (qv_level + 1)
		    ) begin
	      if (is_qv[qv_level]) begin
		highest_qv_value = qv_level;
	      end
	    end
	  end
	  always @(*) begin : p_qv_requests_masked_comb

	    integer		e;
	    integer		qv_level;
	    for (e = 0; (e < REQUESTS); e = (e + 1)) begin
	      for (qv_level = 0; (qv_level < (QV_LEVELS - 1)); qv_level = 
		      (qv_level + 1)) begin
		qv_requests_masked[e][qv_level] = (qv_requests[qv_level][e] &
			(~is_qv[(qv_level + 1)]));
	      end
	      qv_requests_masked[e][(QV_LEVELS - 1)] = qv_requests[(QV_LEVELS -
		      1)][e];
	    end
	  end
	  always @(*) begin : p_highest_mh_comb

	    integer		e;
	    integer		qv_level;
	    for (e = 0; (e < REQUESTS); e = (e + 1)) begin
	      highest_mh_i[e] = (|qv_requests_masked[e]);
	    end
	  end
	end
endmodule
`endcelldefine

