	function automatic overflow;
	input logic		increment;
	input logic
		[31:0]		old_value;
	input logic
		[2:0]		overflow_bit;
	overflow = (increment & (&((128'hffffffffffffffffffffffffffffffff <<
		(8'b1 << overflow_bit)) | {{96 {1'b0}}, old_value})));
	endfunction

