module yamin_dcls_rst_checker(clkin, reset_n, gen_resetn_in, rst_comp_en_ext,
	dftrstdisable, dclsctl_en_rst_i, dclsctl_frc_rst_i, rst_comp_en,
	reset_err, gen_resetn_out);
	parameter		IS_SECONDARY	= 1'b0;
	input			clkin;
	input			reset_n;
	input			gen_resetn_in;
	input			rst_comp_en_ext;
	input			dftrstdisable;
	input			dclsctl_en_rst_i;
	input			dclsctl_frc_rst_i;
	output			rst_comp_en;

	reg			rst_comp_en;
	output			reset_err;
	reg			reset_err;
	output			gen_resetn_out;
	logic			gen_reset_n;
	logic			reset_err_nxt;

	assign reset_err_nxt = (dclsctl_en_rst_i & (dclsctl_frc_rst_i |
		(rst_comp_en ^ rst_comp_en_ext)));

	always_ff @(posedge clkin) reset_err <= reset_err_nxt;

	if (IS_SECONDARY == 0) begin : gen_rst_prim 

	  assign gen_reset_n = reset_n;
	  assign gen_resetn_out = gen_reset_n;
	end
	else  begin : gen_rst_sec 
	  yamin_cell_sync u_sync_rst_sec(
		.clk				(clkin), 
		.reset_n			(reset_n), 
		.in_i				(1'b1), 
		.out_o				(gen_reset_n));

	  assign gen_resetn_out = (gen_reset_n | dftrstdisable);
	end

	if (IS_SECONDARY == 0) begin : gen_rst_comp_en_prim 

	  logic			rst_comp_pre2;
	  logic			rst_comp_pre1;

	  always_ff @(posedge clkin or negedge gen_resetn_in) if (~gen_resetn_in
		  ) begin
	    rst_comp_pre2 <= 1'b0;
	    rst_comp_pre1 <= 1'b0;
	    rst_comp_en <= 1'b0;
	  end
	  else if (~rst_comp_en) begin
	    rst_comp_pre2 <= 1'b1;
	    rst_comp_pre1 <= rst_comp_pre2;
	    rst_comp_en <= rst_comp_pre1;
	  end
	end
	else  begin : gen_rst_comp_en_sec 

	  always_ff @(posedge clkin or negedge gen_resetn_in) if (~gen_resetn_in
		  ) begin
	    rst_comp_en <= 1'b0;
	  end
	  else if (~rst_comp_en) begin
	    rst_comp_en <= 1'b1;
	  end
	end
endmodule
