module css600_or_tree(or_inputs, or_output);
	parameter		NUM_OR_INPUTS	= 2;
	input	[(NUM_OR_INPUTS - 1):0]
				or_inputs;
	output			or_output;
	localparam		ODD_INPUTS	= (NUM_OR_INPUTS % 2);
	localparam		NUM_FIRST_STAGE_GATES
						= ((ODD_INPUTS == 0) ? (
		NUM_OR_INPUTS / 2) : ((NUM_OR_INPUTS - 1) / 2));
	localparam		NUM_OR_GATES	= ((ODD_INPUTS == 0) ? (
		NUM_OR_INPUTS - 1) : (NUM_OR_INPUTS - 2));

	genvar 			i;
	wire	[(NUM_OR_GATES - 1):0]
				or_outputs;

	for (i = 0; (i < NUM_FIRST_STAGE_GATES); i = (i + 1)) begin : 
		gen_first_stage 
	  css600_or u_css600_or(
		.in_a				(or_inputs[(i * 2)]), 
		.in_b				(or_inputs[((i * 2) + 1)]), 
		.out_y				(or_outputs[i]));
	end

	for (i = NUM_FIRST_STAGE_GATES; (i < NUM_OR_GATES); i = (i + 1)) begin :
		gen_remaining 
	  css600_or u_css600_or(
		.in_a				(or_outputs[((i -
		  NUM_FIRST_STAGE_GATES) * 2)]), 
		.in_b				(or_outputs[(((i -
		  NUM_FIRST_STAGE_GATES) * 2) + 1)]), 
		.out_y				(or_outputs[i]));
	end

	if (ODD_INPUTS != 0) begin : gen_or_odd 
	  css600_or u_css600_or(
		.in_a				(or_outputs[(NUM_OR_GATES -
		  1)]), 
		.in_b				(or_inputs[(NUM_OR_INPUTS -
		  1)]), 
		.out_y				(or_output));
	end
	else  begin : gen_final_output 

	  assign or_output = or_outputs[(NUM_OR_GATES - 1)];
	end
endmodule
