	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  strex_in_prog <= 1'b0;
	end
	else if (strex_in_prog_en) begin
	  strex_in_prog <= strex_ack;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  dev_strex_in_prog <= 1'b0;
	end
	else if (dev_strex_in_prog_en) begin
	  dev_strex_in_prog <= next_dev_strex_in_prog;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  strex_on_axi <= 1'b0;
	end
	else if (strex_on_axi_en) begin
	  strex_on_axi <= set_strex_on_axi;
	end
	always_comb  begin : next_axi_user_single_reg_comb
	  axi_user_single_reg_en = 1'b0;
	  next_axi_user_single_reg = 1'bx;
	  if (clear_axi_user_single_reg) begin
	    axi_user_single_reg_en = 1'b1;
	    next_axi_user_single_reg = 1'b0;
	  end
	  else if (set_axi_user_single_reg) begin
	    axi_user_single_reg_en = 1'b1;
	    next_axi_user_single_reg = 1'b1;
	  end
	  else if (toggle_axi_user_single_reg) begin
	    axi_user_single_reg_en = 1'b1;
	    next_axi_user_single_reg = (~axi_user_single_reg);
	  end
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  axi_user_single_reg <= 1'b0;
	end
	else if (axi_user_single_reg_en) begin
	  axi_user_single_reg <= next_axi_user_single_reg;
	end
	always_comb  begin
	  case ({wbuf_has_axi_aw, single_has_axi_aw})
	    2'b0: begin
	      arb_wr_aw_val = 1'b0;
	      arb_wr_aw_id = axi_wid_t'('x);
	      arb_wr_aw_addr = 32'hxxxxxxxx;
	      arb_wr_aw_len = 2'bxx;
	      arb_wr_aw_size = size_t'('x);
	      arb_wr_aw_lock = 1'bx;
	      arb_wr_aw_prot = 2'bxx;
	      arb_wr_aw_master = 1'bx;
	      arb_wr_aw_sparse = 1'bx;
	      arb_wr_aw_attrs = attr_t'('x);
	    end
	    2'b1: begin
	      arb_wr_aw_val = (~(stb_biu_write_strex_i & lsu_biu_kill_ls2_i));
	      arb_wr_aw_id = (stb_biu_write_strex_i ? yamin_pkg::AXI_WID_NC :
		      (attrs_are_dev(stb_biu_write_attrs_i) ?
		      yamin_pkg::AXI_WID_DEV_SO :
		      (attrs_are_ch(stb_biu_write_attrs_i) ?
		      yamin_pkg::AXI_WID_CACHEABLE : yamin_pkg::AXI_WID_NC)));
	      arb_wr_aw_addr = stb_biu_addr_aligned;
	      arb_wr_aw_len = (dev_mini_burst ? 2'b1 : 2'b0);
	      arb_wr_aw_size = (dev_mini_burst ? yamin_pkg::WORD :
		      stb_biu_write_size_i);
	      arb_wr_aw_lock = stb_biu_write_strex_i;
	      arb_wr_aw_prot = {stb_biu_write_ns_attr_i, stb_biu_write_priv_i};
	      arb_wr_aw_master = stb_biu_write_dbg_i;
	      arb_wr_aw_sparse = single_is_sparse;
	      arb_wr_aw_attrs = stb_biu_write_attrs_i;
	    end
	    2'b10: begin
	      arb_wr_aw_val = 1'b1;
	      arb_wr_aw_id = (wbuf_is_for_ev ? yamin_pkg::AXI_WID_EV :
		      (wbuf_attrs_is_cacheable ? yamin_pkg::AXI_WID_CACHEABLE :
		      yamin_pkg::AXI_WID_NC));
	      arb_wr_aw_addr = {wbuf_addr[31:5], wbuf_drain_ptr_addr_offset};
	      arb_wr_aw_len = {(wbuf_top_ptr - wbuf_drain_ptr)};
	      arb_wr_aw_size = yamin_pkg::DWORD;
	      arb_wr_aw_lock = 1'b0;
	      arb_wr_aw_prot = {wbuf_ns_attr, 1'b1};
	      arb_wr_aw_master = wbuf_dbg;
	      arb_wr_aw_sparse = (wbuf_is_for_ev ? 1'b0 : wbuf_burst_is_sparse);
	      arb_wr_aw_attrs = wbuf_attrs;
	    end
	    default: begin
	      arb_wr_aw_val = 1'bx;
	      arb_wr_aw_id = axi_wid_t'('x);
	      arb_wr_aw_addr = 32'hxxxxxxxx;
	      arb_wr_aw_len = 2'bxx;
	      arb_wr_aw_size = size_t'('x);
	      arb_wr_aw_lock = 1'bx;
	      arb_wr_aw_prot = 2'bxx;
	      arb_wr_aw_master = 1'bx;
	      arb_wr_aw_sparse = 1'bx;
	      arb_wr_aw_attrs = attr_t'('x);
	    end
	  endcase
	end
	always_comb  begin
	  case ({wbuf_has_axi_dw, single_has_axi_dw})
	    2'b0: begin
	      arb_wr_dw_val = 1'b0;
	      arb_wr_dw_id = axi_wid_t'('x);
	      arb_wr_dw_data = 'x;
	      arb_wr_dw_strb = 8'hxx;
	      arb_wr_dw_poison = 1'bx;
	      arb_wr_dw_last = 1'bx;
	    end
	    2'b1: begin
	      arb_wr_dw_val = 1'b1;
	      arb_wr_dw_id = (stb_biu_write_strex_i ? yamin_pkg::AXI_WID_NC :
		      (attrs_are_dev(stb_biu_write_attrs_i) ?
		      yamin_pkg::AXI_WID_DEV_SO :
		      (attrs_are_ch(stb_biu_write_attrs_i) ?
		      yamin_pkg::AXI_WID_CACHEABLE : yamin_pkg::AXI_WID_NC)));
	      arb_wr_dw_data = stb_biu_write_data_i;
	      arb_wr_dw_strb = (dev_mini_burst_lo ? (stb_biu_write_wstrb_i &
		      8'b00001111) : (dev_mini_burst_hi ? (stb_biu_write_wstrb_i
		      & 8'b11110000) : stb_biu_write_wstrb_i));
	      arb_wr_dw_poison = 1'b0;
	      arb_wr_dw_last = (single_has_axi_dw & (~dev_mini_burst_lo));
	    end
	    2'b10: begin
	      arb_wr_dw_val = 1'b1;
	      if (wbuf_axi_dw_is_ev) begin
		arb_wr_dw_id = yamin_pkg::AXI_WID_EV;
		arb_wr_dw_data = (scb_ecc_en_i ? wbuf_drain_data_repair :
			wbuf_drain_data);
		arb_wr_dw_poison = (scb_ecc_en_i ? (|wbuf_drain_fatal) : 1'b0);
		arb_wr_dw_strb = wbuf_drain_wstrb;
	      end
	      else
		begin
		  arb_wr_dw_id = (wbuf_axi_dw_is_ch ?
			  yamin_pkg::AXI_WID_CACHEABLE : yamin_pkg::AXI_WID_NC);
		  arb_wr_dw_data = wbuf_drain_data;
		  arb_wr_dw_poison = 1'b0;
		  arb_wr_dw_strb = wbuf_drain_wstrb;
		end
	      arb_wr_dw_last = (wbuf_drain_ptr == wbuf_top_ptr);
	    end
	    default: begin
	      arb_wr_dw_val = 1'bx;
	      arb_wr_dw_id = axi_wid_t'('x);
	      arb_wr_dw_data = 'x;
	      arb_wr_dw_strb = 'x;
	      arb_wr_dw_poison = 1'bx;
	      arb_wr_dw_last = 1'bx;
	    end
	  endcase
	end

	for (i = 0; (i < 4); i = (i + 1)) begin : wbuf_slot_used_gen 

	  always_comb  begin
	    wbuf_slot_used_nrm[i] = ((wbuf_drain_ptr <= i[1:0]) & (wbuf_top_ptr
		    >= i[1:0]));
	    wbuf_slot_used_wrap[i] = ((wbuf_drain_ptr <= i[1:0]) | (wbuf_top_ptr
		    >= i[1:0]));
	  end
	end

	for (i = 0; (i < 8); i = (i + 1)) begin : wbuf_slot0_update 

	  always_comb  begin : next_wbuf_slot0_comb
	    wbuf_slot0_en[i] = 1'b0;
	    next_wbuf_slot0[(i * 8)+:8] = 8'bxxxxxxxx;
	    if (ev_data_val_i | mbist_read_data_psel_mb2_i) begin
	      wbuf_slot0_en[i] = 1'b1;
	      next_wbuf_slot0[(i * 8)+:8] = dcu_biu_line_data_m2_i[(i * 8)+:8];
	    end
	    else if ((wbuf_slot_en[0] && stb_has_wbuf) && 
		    stb_biu_write_wstrb_i[i]) begin
	      wbuf_slot0_en[i] = 1'b1;
	      next_wbuf_slot0[(i * 8)+:8] = stb_biu_write_data_i[(i * 8)+:8];
	    end
	  end
	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    wbuf_slot0[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (wbuf_slot0_en[i]) begin
	    wbuf_slot0[(i * 8)+:8] <= next_wbuf_slot0[(i * 8)+:8];
	  end
	end

	for (i = 0; (i < 8); i = (i + 1)) begin : wbuf_slot1_update 

	  always_comb  begin : next_wbuf_slot1_comb
	    wbuf_slot1_en[i] = 1'b0;
	    next_wbuf_slot1[(i * 8)+:8] = 8'bxxxxxxxx;
	    if (ev_data_val_i | mbist_read_data_psel_mb2_i) begin
	      wbuf_slot1_en[i] = 1'b1;
	      next_wbuf_slot1[(i * 8)+:8] = dcu_biu_line_data_m2_i[(64 + (i *
		      8))+:8];
	    end
	    else if ((wbuf_slot_en[1] && stb_has_wbuf) && 
		    stb_biu_write_wstrb_i[i]) begin
	      wbuf_slot1_en[i] = 1'b1;
	      next_wbuf_slot1[(i * 8)+:8] = stb_biu_write_data_i[(i * 8)+:8];
	    end
	  end
	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    wbuf_slot1[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (wbuf_slot1_en[i]) begin
	    wbuf_slot1[(i * 8)+:8] <= next_wbuf_slot1[(i * 8)+:8];
	  end
	end

	for (i = 0; (i < 8); i = (i + 1)) begin : wbuf_slot2_update 

	  always_comb  begin : next_wbuf_slot2_comb
	    wbuf_slot2_en[i] = 1'b0;
	    next_wbuf_slot2[(i * 8)+:8] = 8'bxxxxxxxx;
	    if (ev_data_val_i | mbist_read_data_psel_mb2_i) begin
	      wbuf_slot2_en[i] = 1'b1;
	      next_wbuf_slot2[(i * 8)+:8] = dcu_biu_line_data_m2_i[(128 + (i *
		      8))+:8];
	    end
	    else if ((wbuf_slot_en[2] && stb_has_wbuf) && 
		    stb_biu_write_wstrb_i[i]) begin
	      wbuf_slot2_en[i] = 1'b1;
	      next_wbuf_slot2[(i * 8)+:8] = stb_biu_write_data_i[(i * 8)+:8];
	    end
	  end
	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    wbuf_slot2[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (wbuf_slot2_en[i]) begin
	    wbuf_slot2[(i * 8)+:8] <= next_wbuf_slot2[(i * 8)+:8];
	  end
	end

	for (i = 0; (i < 8); i = (i + 1)) begin : wbuf_slot3_update 

	  always_comb  begin : next_wbuf_slot3_comb
	    wbuf_slot3_en[i] = 1'b0;
	    next_wbuf_slot3[(i * 8)+:8] = 8'bxxxxxxxx;
	    if (ev_data_val_i | mbist_read_data_psel_mb2_i) begin
	      wbuf_slot3_en[i] = 1'b1;
	      next_wbuf_slot3[(i * 8)+:8] = dcu_biu_line_data_m2_i[(192 + (i *
		      8))+:8];
	    end
	    else if ((wbuf_slot_en[3] && stb_has_wbuf) && 
		    stb_biu_write_wstrb_i[i]) begin
	      wbuf_slot3_en[i] = 1'b1;
	      next_wbuf_slot3[(i * 8)+:8] = stb_biu_write_data_i[(i * 8)+:8];
	    end
	  end
	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    wbuf_slot3[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (wbuf_slot3_en[i]) begin
	    wbuf_slot3[(i * 8)+:8] <= next_wbuf_slot3[(i * 8)+:8];
	  end
	end

	for (i = 0; (i < 4); i = (i + 1)) begin : wbuf_wstrb_update 

	  assign next_wbuf_wstrb[(i * 8)+:8] = ((wbuf_slot_val[i] ?
		  wbuf_wstrb[(i * 8)+:8] : {8 {1'b0}}) | (ev_data_val_i ? {8
		  {1'b1}} : stb_biu_write_wstrb_i));

	  always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n)
		  begin
	    wbuf_wstrb[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (wbuf_slot_en[i]) begin
	    wbuf_wstrb[(i * 8)+:8] <= next_wbuf_wstrb[(i * 8)+:8];
	  end
	end

	if ((DCACHE == 1) & (ECC == 1)) begin : gen_wbuf_ecc_dcache 

	  logic	[6:0]		bank_syndrome[7:0];

	  logic			wbuf_syndrome_en;

	  assign wbuf_syndrome_en = (ev_data_val_i | mbist_read_data_psel_mb2_i)
		  ;
	  assign flop_parity_auto__wbuf_syndrome_en = wbuf_syndrome_en;

	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    wbuf_syndrome <= {56 {1'b0}};
	  end
	  else if (wbuf_syndrome_en) begin
	    wbuf_syndrome <= dcu_biu_line_syndrome_m2_i;
	  end

	  for (bank = 0; (bank < 8); bank = (bank + 1)) begin : gen_bank 
	    yamin_ecc_repair #(.SCHEME(yamin_ecc_pkg::ECC_SECDED_41_7)) 
		    u_line_fatal(
		.data_i				('0), 
		.syndrome_i			(bank_syndrome[bank]), 
		.data_mask_i			({{32 {1'b1}}, {9 {1'b0}}}), 
		    .data_o(), 
		.fatal_o			(wbuf_uncorr_ecc_err[bank]));

	    assign bank_syndrome[bank] = wbuf_syndrome[(bank * 7)+:7];
	    assign wbuf_ecc_err[bank] = (|bank_syndrome[bank]);
	  end
	end
	else  begin : gen_wbuf_ecc_no_ecc 

	  assign wbuf_syndrome = {56 {1'b0}};
	  assign wbuf_ecc_err = {8 {1'b0}};
	  assign wbuf_uncorr_ecc_err = {8 {1'b0}};
	end

	if (DCACHE == 1) begin : gen_sent_ch_addr_dcache 

	  reg			sent_ev_addr_q;

	  assign sent_ev_addr = sent_ev_addr_q;
	  assign flop_parity_auto__sent_ev_addr_q = sent_ev_addr_q;

	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    sent_ev_addr_q <= 1'b0;
	  end
	  else if (wbuf_send_addr) begin
	    sent_ev_addr_q <= wbuf_is_for_ev;
	  end
	end
	else  begin : gen_sent_ch_addr_no_dcache 

	  assign sent_ev_addr = 1'b0;
	end

	if (DCACHE == 1) begin : gen_wbuf_is_for_ev_dcache 

	  reg			wbuf_is_for_ev_q;
	  logic			wbuf_is_for_ev_q_en;

	  assign wbuf_is_for_ev_q_en = (ev_has_wbuf | wbuf_send_addr);
	  assign wbuf_is_for_ev = wbuf_is_for_ev_q;
	  assign flop_parity_auto__wbuf_is_for_ev_q_en = wbuf_is_for_ev_q_en;
	  assign flop_parity_auto__wbuf_is_for_ev_q = wbuf_is_for_ev_q;

	  always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n)
		  begin
	    wbuf_is_for_ev_q <= 1'b0;
	  end
	  else if (wbuf_is_for_ev_q_en) begin
	    wbuf_is_for_ev_q <= ev_has_wbuf;
	  end
	end
	else  begin : gen_wbuf_is_for_ev_no_dcache 

	  assign wbuf_is_for_ev = 1'b0;
	end

	if ((DCACHE == 1) & (ECC == 1)) begin : gen_ecc_repair_ecc 

	  wire	[13:0]		wbuf_drain_syndrome;
	  logic	[8:0]		unused_repair_0;
	  logic	[8:0]		unused_repair_1;
	  yamin_ecc_repair #(.SCHEME(yamin_ecc_pkg::ECC_SECDED_41_7)) u_repair0(
		.data_i				({wbuf_drain_data[31:0], {9
		  {1'b0}}}), 
		.syndrome_i			(wbuf_drain_syndrome[6:0]), 
		.data_mask_i			({{32 {1'b1}}, {9 {1'b0}}}), 
		.data_o				({wbuf_drain_data_repair[31:0],
		  unused_repair_0}), .fatal_o());
	  yamin_ecc_repair #(.SCHEME(yamin_ecc_pkg::ECC_SECDED_41_7)) u_repair1(
		.data_i				({wbuf_drain_data[63:32], {9
		  {1'b0}}}), 
		.syndrome_i			(wbuf_drain_syndrome[13:7]), 
		.data_mask_i			({{32 {1'b1}}, {9 {1'b0}}}), 
		.data_o				({wbuf_drain_data_repair[63:32],
		  unused_repair_1}), .fatal_o());
	  wire	[1:0]		wbuf_drain_ecc_err = 
		  {(|wbuf_drain_syndrome[13:7]), (|wbuf_drain_syndrome[6:0])};
	  wire	[5:0]		wbuf_drain_ecc_chk = {(~|wbuf_drain_fatal),
		  (~|((~wbuf_drain_fatal) & wbuf_drain_ecc_err)),
		  (&wbuf_drain_fatal), (&((~wbuf_drain_fatal) &
		  wbuf_drain_ecc_err)), (|wbuf_drain_fatal),
		  (|((~wbuf_drain_fatal) & wbuf_drain_ecc_err))};

	  assign wbuf_drain_syndrome = ((wbuf_drain_ptr_mbist == 2'b0) ?
		  wbuf_syndrome[0+:14] : ((wbuf_drain_ptr_mbist == 2'b1) ?
		  wbuf_syndrome[14+:14] : ((wbuf_drain_ptr_mbist == 2'b10) ?
		  wbuf_syndrome[28+:14] : wbuf_syndrome[42+:14])));
	  assign wbuf_drain_fatal = ((wbuf_drain_ptr_mbist == 2'b0) ?
		  wbuf_uncorr_ecc_err[0+:2] : ((wbuf_drain_ptr_mbist == 2'b1) ?
		  wbuf_uncorr_ecc_err[2+:2] : ((wbuf_drain_ptr_mbist == 2'b10) ?
		  wbuf_uncorr_ecc_err[4+:2] : wbuf_uncorr_ecc_err[6+:2])));
	  assign mbist_wbuf_drain_ecc_chk_m3_o = wbuf_drain_ecc_chk;
	  assign mbist_wbuf_drain_corrctn_m3_o = wbuf_drain_data_repair;
	end
	else  begin : gen_ecc_repair_no_ecc 

	  assign wbuf_drain_fatal = 2'b0;
	  assign wbuf_drain_data_repair = wbuf_drain_data;
	  assign mbist_wbuf_drain_ecc_chk_m3_o = 6'b0;
	  assign mbist_wbuf_drain_corrctn_m3_o = {64 {1'b0}};
	end

	if (DCACHE == 1) begin : gen_dcache_no_write_alloc 

	  wire			wbuf_send_addr_incomplete = (wbuf_send_addr & ((
		  wbuf_drain_ptr != (wbuf_top_ptr + 2'b1)) | (~(&wbuf_wstrb))));
	  wire			wbuf_send_addr_complete = (wbuf_send_addr & ((
		  wbuf_drain_ptr == (wbuf_top_ptr + 2'b1)) & (&wbuf_wstrb)));
	  wire			can_interrupt_wbuf = (ev_wants_wbuf_i | 
		  watchcat_trigger_drain);
	  reg			wbuf_interrupted;
	  logic			wbuf_interrupted_en;
	  logic			next_wbuf_interrupted;

	  assign wbuf_cancel_no_write_alloc = (no_write_alloc_mode_i &
		  (((|lfb_hazard_writes_i) & (~wbuf_is_for_ev)) |
		  (wbuf_send_addr_incomplete & (~(can_interrupt_wbuf |
		  wbuf_interrupted)))));
	  assign flop_parity_auto__next_wbuf_interrupted = next_wbuf_interrupted
		  ;
	  assign flop_parity_auto__wbuf_interrupted_en = wbuf_interrupted_en;
	  assign flop_parity_auto__wbuf_interrupted = wbuf_interrupted;

	  always_comb  begin : next_wbuf_interrupted_comb
	    wbuf_interrupted_en = 1'b0;
	    next_wbuf_interrupted = 1'bx;
	    if (~no_write_alloc_mode_i) begin
	      wbuf_interrupted_en = 1'b1;
	      next_wbuf_interrupted = 1'b0;
	    end
	    else if (wbuf_send_addr_complete & (~wbuf_is_for_ev)) begin
	      wbuf_interrupted_en = 1'b1;
	      next_wbuf_interrupted = 1'b0;
	    end
	    else if (wbuf_send_addr_incomplete & (~wbuf_is_for_ev)) begin
	      wbuf_interrupted_en = 1'b1;
	      next_wbuf_interrupted = can_interrupt_wbuf;
	    end
	  end
	  always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n)
		  begin
	    wbuf_interrupted <= 1'b0;
	  end
	  else if (wbuf_interrupted_en) begin
	    wbuf_interrupted <= next_wbuf_interrupted;
	  end
	end
	else  begin : gen_no_dcache_no_write_alloc 

	  assign wbuf_cancel_no_write_alloc = 1'b0;
	end

	if ((DCACHE == 0) | (ECC == 0)) begin : gen_unused_no_ecc 

