	function automatic f_rgn_hit;
	input logic		rgn_en;
	input logic
		[31:5]		rgn_base_addr;
	input logic
		[31:5]		rgn_limit_addr;
	input logic
		[31:5]		addr;
	begin
	  f_rgn_hit = ((addr >= {(rgn_base_addr[31] | (~rgn_en)),
		  rgn_base_addr[30:5]}) & (addr <= {(rgn_limit_addr[31] &
		  rgn_en), rgn_limit_addr[30:5]}));
	end
	endfunction

	function automatic f_rgn_ap_fault;
	input logic
		[1:0]		ap;
	input logic		priv;
	input logic		write;
	begin
	  case (ap)
	    2'b0:
	      f_rgn_ap_fault = (~priv);
	    2'b1:
	      f_rgn_ap_fault = 1'b0;
	    2'b10:
	      f_rgn_ap_fault = ((~priv) | write);
	    2'b11:
	      f_rgn_ap_fault = write;
	    default:
	      f_rgn_ap_fault = 1'bx;
	  endcase
	end
	endfunction

	function automatic [7:0] f_dmm_attr;
	input logic
		[31:29]		addr;
	input logic		addr_ppb;
	begin
	  case (addr[31:29])
	    3'b0:
	      f_dmm_attr = {2 {4'b0010}};
	    3'b1:
	      f_dmm_attr = {2 {4'b0111}};
	    3'h2:
	      f_dmm_attr = {4'b0, 4'b0100};
	    3'h3:
	      f_dmm_attr = {2 {4'b0111}};
	    3'h4:
	      f_dmm_attr = {2 {4'b0010}};
	    3'h5, 3'h6:
	      f_dmm_attr = {4'b0, 4'b0100};
	    3'h7:
	      f_dmm_attr = {4'b0, 1'b0, (~addr_ppb), 2'b0};
	    default:
	      f_dmm_attr = 8'bxxxxxxxx;
	  endcase
	end
	endfunction

	function automatic f_dmm_xn;
	input logic
		[31:29]		addr;
	begin
	  case (addr[31:29])
	    3'b0, 3'b1, 3'h3, 3'h4:
	      f_dmm_xn = 1'b0;
	    3'h2, 3'h5, 3'h6, 3'h7:
	      f_dmm_xn = 1'b1;
	    default:
	      f_dmm_xn = 1'bx;
	  endcase
	end
	endfunction

	function automatic [1:0] f_dmm_sh;
	input logic
		[31:29]		addr;
	begin
	  case (addr[31:29])
	    3'b0, 3'b1, 3'h3, 3'h4:
	      f_dmm_sh = 2'b0;
	    3'h2, 3'h5, 3'h6, 3'h7:
	      f_dmm_sh = 2'b10;
	    default:
	      f_dmm_sh = 2'bxx;
	  endcase
	end
	endfunction

