	logic			ctrl_privdefena_q;
	logic			ctrl_hfnmiena_q;
	logic			ctrl_enable_q;
	logic	[(MPU_LOG2 - 1):0]
				rnr_region_q;

	logic	[31:5]		rbar_base_q[(MPU - 1):0];
	logic	[1:0]		rbar_sh_q[(MPU - 1):0];
	logic	[1:0]		rbar_ap_q[(MPU - 1):0];
	logic	[(MPU - 1):0]	rbar_xn_q;
	logic	[31:5]		rlar_limit_q[(MPU - 1):0];
	logic	[2:0]		rlar_attrindx_q[(MPU - 1):0];
	logic	[(MPU - 1):0]	rlar_pxn_q;
	logic	[(MPU - 1):0]	rlar_en_q;
	logic	[31:0]		mair0_q;
	logic	[31:0]		mair1_q;
	wire			ctrl_privdefena;
	wire			ctrl_hfnmiena;
	wire			ctrl_enable;
	wire	[(MPU_LOG2 - 1):0]
				rnr_region;
	wire[31:5]		rbar_base[(MPU_2 - 1):0];
	wire[1:0]		rbar_sh[(MPU_2 - 1):0];
	wire[1:0]		rbar_ap[(MPU_2 - 1):0];
	wire	[(MPU_2 - 1):0]	rbar_xn;
	wire[31:5]		rlar_limit[(MPU_2 - 1):0];
	wire[2:0]		rlar_attrindx[(MPU_2 - 1):0];
	wire	[(MPU_2 - 1):0]	rlar_pxn;
	wire	[(MPU_2 - 1):0]	rlar_en;
	wire	[31:0]		mair0;
	wire	[31:0]		mair1;
	logic			disable_q;
	wire			reg_write = ((reg_write_i & (~disable_q)) & (~
		lock_i));
	wire			reg_read = (reg_read_i & (~disable_q));
	wire			ctrl_we = (reg_write & reg_sel_i[MPU_CTRL]);
	wire	[31:0]		ctrl_rdata = {29'b0, ctrl_privdefena,
		ctrl_hfnmiena, ctrl_enable};
	wire			rnr_we = (reg_write & reg_sel_i[MPU_RNR]);
	wire	[(MPU_LOG2 - 1):0]
				rnr_region_nxt = reg_wdata_i[(MPU_LOG2 - 1):0];
	wire	[31:0]		rnr_rdata = {{(32 - MPU_LOG2) {1'b0}},
		rnr_region};
	wire	[(MPU_LOG2 - 1):0]
				region_rbar;
	wire	[(MPU_LOG2 - 1):0]
				region_rlar;
	wire			reg_sel_rbar_alias = ((reg_sel_i[MPU_RBAR_A1] | 
		reg_sel_i[MPU_RBAR_A2]) | reg_sel_i[MPU_RBAR_A3]);
	wire	[1:0]		region_rbar_alias = (((({2
		{reg_sel_i[MPU_RBAR_A1]}} & 2'b1) | ({2
		{reg_sel_i[MPU_RBAR_A2]}} & 2'b10)) | ({2
		{reg_sel_i[MPU_RBAR_A3]}} & 2'b11)) | ({2
		{(~reg_sel_rbar_alias)}} & rnr_region[1:0]));
	wire			reg_sel_rlar_alias = ((reg_sel_i[MPU_RLAR_A1] | 
		reg_sel_i[MPU_RLAR_A2]) | reg_sel_i[MPU_RLAR_A3]);
	wire	[1:0]		region_rlar_alias = (((({2
		{reg_sel_i[MPU_RLAR_A1]}} & 2'b1) | ({2
		{reg_sel_i[MPU_RLAR_A2]}} & 2'b10)) | ({2
		{reg_sel_i[MPU_RLAR_A3]}} & 2'b11)) | ({2
		{(~reg_sel_rlar_alias)}} & rnr_region[1:0]));
	wire			reg_sel_rbar = (((reg_sel_i[MPU_RBAR] | 
		reg_sel_i[MPU_RBAR_A1]) | reg_sel_i[MPU_RBAR_A2]) | 
		reg_sel_i[MPU_RBAR_A3]);
	wire			reg_sel_rlar = (((reg_sel_i[MPU_RLAR] | 
		reg_sel_i[MPU_RLAR_A1]) | reg_sel_i[MPU_RLAR_A2]) | 
		reg_sel_i[MPU_RLAR_A3]);
	logic			flop_parity_auto__rlar_we[(MPU_2 - 1):0];
	logic			flop_parity_auto__rbar_we[(MPU_2 - 1):0];
	genvar 			gi;
	wire	[31:0]		rbar_rdata = {rbar_base[region_rbar],
		rbar_sh[region_rbar], rbar_ap[region_rbar],
		rbar_xn[region_rbar]};
	wire	[31:0]		rlar_rdata = {rlar_limit[region_rlar],
		rlar_pxn[region_rlar], rlar_attrindx[region_rlar],
		rlar_en[region_rlar]};
	wire			mair0_we = (reg_write & reg_sel_i[MPU_MAIR0]);
	wire			mair1_we = (reg_write & reg_sel_i[MPU_MAIR1]);
	wire	[31:0]		mair0_rdata = mair0;
	wire	[31:0]		mair1_rdata = mair1;
	wire	[63:0]		mair = {mair1, mair0};
	wire	[31:0]		type_rdata = {8'b0, 8'b0, 3'b0, cfg_mpu[4:0],
		8'b0};
	wire	[12:0]		reg_sel_rd = ((reg_sel_i & {13 {reg_read}}) & 
		{13 {(|cfg_mpu)}});
	wire			reg_sel_rbar_rd = ((reg_sel_rbar & reg_read) & (
		|cfg_mpu));
	wire			reg_sel_rlar_rd = ((reg_sel_rlar & reg_read) & (
		|cfg_mpu));

	assign ctrl_privdefena = ctrl_privdefena_q;
	assign ctrl_hfnmiena = ctrl_hfnmiena_q;
	assign ctrl_enable = ctrl_enable_q;
	assign rnr_region = (cfg_mpu_rnr_mask[(MPU_LOG2 - 1):0] & rnr_region_q);
	assign mair0 = mair0_q;
	assign mair1 = mair1_q;
	assign reg_rdata_o = ((((((({32 {reg_sel_rd[MPU_TYPE]}} & type_rdata) |
		({32 {reg_sel_rd[MPU_CTRL]}} & ctrl_rdata)) | ({32
		{reg_sel_rd[MPU_RNR]}} & rnr_rdata)) | ({32 {reg_sel_rbar_rd}} &
		rbar_rdata)) | ({32 {reg_sel_rlar_rd}} & rlar_rdata)) | ({32
		{reg_sel_rd[MPU_MAIR0]}} & mair0_rdata)) | ({32
		{reg_sel_rd[MPU_MAIR1]}} & mair1_rdata));
	assign ctrl_privdefena_o = ctrl_privdefena;
	assign ctrl_hfnmiena_o = ctrl_hfnmiena;
	assign ctrl_enable_o = ctrl_enable;

	function automatic f_rgn_hit;
	input logic		rgn_en;
	input logic
		[31:5]		rgn_base_addr;
	input logic
		[31:5]		rgn_limit_addr;
	input logic
		[31:5]		addr;
	begin
	  f_rgn_hit = ((addr >= {(rgn_base_addr[31] | (~rgn_en)),
		  rgn_base_addr[30:5]}) & (addr <= {(rgn_limit_addr[31] &
		  rgn_en), rgn_limit_addr[30:5]}));
	end
	endfunction

	always_ff @(posedge clk or negedge po_reset_n) if (~po_reset_n) begin
	  disable_q <= 1'b0;
	end
	else if (reg_first_cycle_po_i) begin
	  disable_q <= disable_i;
	end
	always_ff @(posedge pclk or negedge reset_n) begin
	  if (~reset_n) begin
	    ctrl_privdefena_q <= 1'b0;
	    ctrl_hfnmiena_q <= 1'b0;
	    ctrl_enable_q <= 1'b0;
	  end
	  else if (ctrl_we) begin
	    ctrl_privdefena_q <= reg_wdata_i[2];
	    ctrl_hfnmiena_q <= reg_wdata_i[1];
	    ctrl_enable_q <= reg_wdata_i[0];
	  end
	end
	always_ff @(posedge pclk or negedge rar_reset_n) if (~rar_reset_n) begin
	  rnr_region_q <= {MPU_LOG2 {1'b1}};
	end
	else if (rnr_we) begin
	  rnr_region_q <= rnr_region_nxt;
	end
	always_ff @(posedge pclk or negedge rar_reset_n) if (~rar_reset_n) begin
	  mair0_q <= {32 {1'b0}};
	end
	else if (mair0_we) begin
	  mair0_q <= reg_wdata_i[31:0];
	end
	always_ff @(posedge pclk or negedge rar_reset_n) if (~rar_reset_n) begin
	  mair1_q <= {32 {1'b0}};
	end
	else if (mair1_we) begin
	  mair1_q <= reg_wdata_i[31:0];
	end

	if (MPU_LOG2 > 2) begin : gen_rnr_alias_pad 

	  assign region_rbar = {rnr_region[(MPU_LOG2 - 1):2],
		  region_rbar_alias[1:0]};
	  assign region_rlar = {rnr_region[(MPU_LOG2 - 1):2],
		  region_rlar_alias[1:0]};
	end
	else  begin : gen_rnr_alias_no_pad 

	  assign region_rbar = region_rbar_alias;
	  assign region_rlar = region_rlar_alias;
	end

	for (gi = 0; (gi < MPU_2); gi = (gi + 1)) begin : gen_rgn 

	  if (gi < MPU) begin : gen_reg 

	    wire		rbar_we = (((reg_write & reg_sel_rbar) & (
		    region_rbar == gi[(MPU_LOG2 - 1):0])) | 
		    reg_first_cycle_sys_i);
	    wire		rlar_we = (((reg_write & reg_sel_rlar) & (
		    region_rlar == gi[(MPU_LOG2 - 1):0])) | 
		    reg_first_cycle_sys_i);

	    assign rbar_base[gi] = rbar_base_q[gi];
	    assign rbar_sh[gi] = rbar_sh_q[gi];
	    assign rbar_ap[gi] = rbar_ap_q[gi];
	    assign rbar_xn[gi] = rbar_xn_q[gi];
	    assign rlar_en[gi] = rlar_en_q[gi];
	    assign rlar_limit[gi] = rlar_limit_q[gi];
	    assign rlar_attrindx[gi] = rlar_attrindx_q[gi];
	    assign rlar_pxn[gi] = rlar_pxn_q[gi];
	    assign flop_parity_auto__rlar_we[gi] = rlar_we;
	    assign flop_parity_auto__rbar_we[gi] = rbar_we;

	    always_ff @(posedge pclk or negedge rar_reset_n) if (~rar_reset_n) 
		    begin
	      rbar_base_q[gi] <= {27 {1'b1}};
	      rbar_sh_q[gi] <= {2 {1'b1}};
	      rbar_ap_q[gi] <= {2 {1'b1}};
	      rbar_xn_q[gi] <= 1'b1;
	    end
	    else if (rbar_we) begin
	      rbar_base_q[gi] <= reg_wdata_i[31:5];
	      rbar_sh_q[gi] <= reg_wdata_i[4:3];
	      rbar_ap_q[gi] <= reg_wdata_i[2:1];
	      rbar_xn_q[gi] <= reg_wdata_i[0];
	    end
	    always_ff @(posedge pclk or negedge reset_n) if (~reset_n) begin
	      rlar_en_q[gi] <= 1'b0;
	    end
	    else if (rlar_we) begin
	      rlar_en_q[gi] <= reg_wdata_i[0];
	    end
	    always_ff @(posedge pclk or negedge rar_reset_n) if (~rar_reset_n) 
		    begin
	      rlar_limit_q[gi] <= {27 {1'b1}};
	      rlar_pxn_q[gi] <= 1'b1;
	      rlar_attrindx_q[gi] <= {3 {1'b1}};
	    end
	    else if (rlar_we) begin
	      rlar_limit_q[gi] <= reg_wdata_i[31:5];
	      rlar_pxn_q[gi] <= reg_wdata_i[4];
	      rlar_attrindx_q[gi] <= reg_wdata_i[3:1];
	    end
	  end
	  else  begin : gen_n_reg 

	    assign rbar_base[gi] = 27'b0;
	    assign rbar_sh[gi] = 2'b0;
	    assign rbar_ap[gi] = 2'b0;
	    assign rbar_xn[gi] = 1'b0;
	    assign rlar_en[gi] = 1'b0;
	    assign rlar_limit[gi] = 27'b0;
	    assign rlar_attrindx[gi] = 3'b0;
	    assign rlar_pxn[gi] = 1'b0;
	  end
	end

	for (gi = 0; (gi < MPU_MAX); gi = (gi + 1)) begin : gen_reg_1dim 

	  if (gi < MPU) begin : gen_reg 

	    assign rbar_base_o[((27 * (gi + 1)) - 1)-:27] = rbar_base[gi];
	    assign rbar_sh_o[((2 * (gi + 1)) - 1)-:2] = rbar_sh[gi];
	    assign rbar_ap_o[((2 * (gi + 1)) - 1)-:2] = rbar_ap[gi];
	    assign rbar_xn_o[gi] = rbar_xn[gi];
	    assign rlar_limit_o[((27 * (gi + 1)) - 1)-:27] = rlar_limit[gi];
	    assign rlar_pxn_o[gi] = rlar_pxn[gi];
	    assign rlar_en_o[gi] = rlar_en[gi];
	    assign mair_attr_o[((8 * (gi + 1)) - 1)-:8] = mair[(8 *
		    rlar_attrindx[gi])+:8];
	  end
	  else  begin : gen_n_reg 

	    assign rbar_base_o[((27 * (gi + 1)) - 1)-:27] = 27'b0;
	    assign rbar_sh_o[((2 * (gi + 1)) - 1)-:2] = 2'b0;
	    assign rbar_ap_o[((2 * (gi + 1)) - 1)-:2] = 2'b0;
	    assign rbar_xn_o[gi] = 1'b0;
	    assign rlar_limit_o[((27 * (gi + 1)) - 1)-:27] = 27'b0;
	    assign rlar_pxn_o[gi] = 1'b0;
	    assign rlar_en_o[gi] = 1'b0;
	    assign mair_attr_o[((8 * (gi + 1)) - 1)-:8] = 8'b0;
	  end
	end

	if (FLOPPARITY) begin : g_flop_parity 

	  logic			flop_parity_fault_0;
	  logic			flop_parity_fault_1;
	  logic			flop_parity_fault_2;
	  logic			flop_parity_fault_3;
	  logic			flop_parity_fault_4;
	  logic	[(MPU_2 - 1):0]	flop_parity_fault_5;
	  logic	[(MPU_2 - 1):0]	flop_parity_fault_6;
	  logic	[(MPU_2 - 1):0]	flop_parity_fault_7;
	  localparam		FAULT_WIDTH_AUTO
						= ((((((($bits(
		  flop_parity_fault_0) + $bits(flop_parity_fault_1)) + $bits(
		  flop_parity_fault_2)) + $bits(flop_parity_fault_3)) + $bits(
		  flop_parity_fault_4)) + $bits(flop_parity_fault_5)) + $bits(
		  flop_parity_fault_6)) + $bits(flop_parity_fault_7));
	  logic	[(FAULT_WIDTH_AUTO - 1):0]
				flop_parity_fault_auto;
	  genvar 		gi;
	  yamin_flop_parity_fault_tree #(.WIDTH_AUTO(
		  $bits(flop_parity_fault_auto)), .WIDTH_MANUAL(0), .MODULE_NAME
		  ("yamin_mau_reg"), .REGISTER_OUTPUT(0)) 
		  u_flop_parity_fault_tree(
		.clk				(1'b0), 
		.reset_n			(1'b1), 
		.flop_parity_fault_auto_i	(flop_parity_fault_auto), 
		.flop_parity_fault_manual_i	(1'b0), 
		.flop_parity_fault_o		(flop_parity_fault_o));

	  assign flop_parity_fault_auto = {flop_parity_fault_0,
		  flop_parity_fault_1, flop_parity_fault_2, flop_parity_fault_3,
		  flop_parity_fault_4, flop_parity_fault_5, flop_parity_fault_6,
		  flop_parity_fault_7};

	  if (1) begin : g_flop_parity_0 
	    localparam		FLOP_GROUP_WIDTH
						= (($bits(ctrl_enable_q) + $bits
		    (ctrl_hfnmiena_q)) + $bits(ctrl_privdefena_q));
	    localparam		FLOP_GROUP_RESET_VALUE
						= {1'b0, 1'b0, 1'b0};

	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_0;
	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_0_next;
	    logic		flop_group_0_en;
	    yamin_flop_parity_fault_detection #(.WIDTH(FLOP_GROUP_WIDTH), .
		    RESET_VALUE(FLOP_GROUP_RESET_VALUE), .ID_NAME(
		    "yamin_mau_reg"), .ID_NUMBER("0"), .PARITY_CALC_WIDTH(8)) 
		    u_flop_parity_fault_detection_0(
		.clk				(pclk), 
		.reset_n			(reset_n), 
		.flop_enable_i			(flop_group_0_en), 
		.flop_i				(flop_group_0), 
		.flop_next_i			(flop_group_0_next), 
		.fault_o			(flop_parity_fault_0));

	    assign flop_group_0_next = {reg_wdata_i[0], reg_wdata_i[1],
		    reg_wdata_i[2]};
	    assign flop_group_0 = {ctrl_enable_q, ctrl_hfnmiena_q,
		    ctrl_privdefena_q};
	    assign flop_group_0_en = ctrl_we;
	  end

	  if (1) begin : g_flop_parity_1 
	    localparam		FLOP_GROUP_WIDTH
						= $bits(disable_q);
	    localparam		FLOP_GROUP_RESET_VALUE
						= {1'b0};

	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_1;
	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_1_next;
	    logic		flop_group_1_en;
	    yamin_flop_parity_fault_detection #(.WIDTH(FLOP_GROUP_WIDTH), .
		    RESET_VALUE(FLOP_GROUP_RESET_VALUE), .ID_NAME(
		    "yamin_mau_reg"), .ID_NUMBER("1"), .PARITY_CALC_WIDTH(8)) 
		    u_flop_parity_fault_detection_1(
		.clk				(clk), 
		.reset_n			(po_reset_n), 
		.flop_enable_i			(flop_group_1_en), 
		.flop_i				(flop_group_1), 
		.flop_next_i			(flop_group_1_next), 
		.fault_o			(flop_parity_fault_1));

	    assign flop_group_1_next = disable_i;
	    assign flop_group_1 = disable_q;
	    assign flop_group_1_en = reg_first_cycle_po_i;
	  end

	  if (1) begin : g_flop_parity_2 
	    localparam		FLOP_GROUP_WIDTH
						= $bits(mair0_q);
	    localparam		FLOP_GROUP_RESET_VALUE
						= {{32 {1'b0}}};

	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_2;
	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_2_next;
	    logic		flop_group_2_en;
	    yamin_flop_parity_fault_detection #(.WIDTH(FLOP_GROUP_WIDTH), .
		    RESET_VALUE(FLOP_GROUP_RESET_VALUE), .ID_NAME(
		    "yamin_mau_reg"), .ID_NUMBER("2"), .PARITY_CALC_WIDTH(8)) 
		    u_flop_parity_fault_detection_2(
		.clk				(pclk), 
		.reset_n			(rar_reset_n), 
		.flop_enable_i			(flop_group_2_en), 
		.flop_i				(flop_group_2), 
		.flop_next_i			(flop_group_2_next), 
		.fault_o			(flop_parity_fault_2));

	    assign flop_group_2_next = reg_wdata_i[31:0];
	    assign flop_group_2 = mair0_q;
	    assign flop_group_2_en = mair0_we;
	  end

	  if (1) begin : g_flop_parity_3 
	    localparam		FLOP_GROUP_WIDTH
						= $bits(mair1_q);
	    localparam		FLOP_GROUP_RESET_VALUE
						= {{32 {1'b0}}};

	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_3;
	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_3_next;
	    logic		flop_group_3_en;
	    yamin_flop_parity_fault_detection #(.WIDTH(FLOP_GROUP_WIDTH), .
		    RESET_VALUE(FLOP_GROUP_RESET_VALUE), .ID_NAME(
		    "yamin_mau_reg"), .ID_NUMBER("3"), .PARITY_CALC_WIDTH(8)) 
		    u_flop_parity_fault_detection_3(
		.clk				(pclk), 
		.reset_n			(rar_reset_n), 
		.flop_enable_i			(flop_group_3_en), 
		.flop_i				(flop_group_3), 
		.flop_next_i			(flop_group_3_next), 
		.fault_o			(flop_parity_fault_3));

	    assign flop_group_3_next = reg_wdata_i[31:0];
	    assign flop_group_3 = mair1_q;
	    assign flop_group_3_en = mair1_we;
	  end

	  if (1) begin : g_flop_parity_4 
	    localparam		FLOP_GROUP_WIDTH
						= $bits(rnr_region_q);
	    localparam		FLOP_GROUP_RESET_VALUE
						= {{MPU_LOG2 {1'b1}}};

	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_4;
	    logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_4_next;
	    logic		flop_group_4_en;
	    yamin_flop_parity_fault_detection #(.WIDTH(FLOP_GROUP_WIDTH), .
		    RESET_VALUE(FLOP_GROUP_RESET_VALUE), .ID_NAME(
		    "yamin_mau_reg"), .ID_NUMBER("4"), .PARITY_CALC_WIDTH(8)) 
		    u_flop_parity_fault_detection_4(
		.clk				(pclk), 
		.reset_n			(rar_reset_n), 
		.flop_enable_i			(flop_group_4_en), 
		.flop_i				(flop_group_4), 
		.flop_next_i			(flop_group_4_next), 
		.fault_o			(flop_parity_fault_4));

	    assign flop_group_4_next = rnr_region_nxt;
	    assign flop_group_4 = rnr_region_q;
	    assign flop_group_4_en = rnr_we;
	  end

	  for (gi = 0; (gi < MPU_2); gi = (gi + 1)) begin : g_flop_parity_5_a 

	    if (gi < MPU) begin : g_flop_parity_5_b 
	      localparam	FLOP_GROUP_WIDTH
						= ((($bits(rbar_ap_q[gi]) + 
		      $bits(rbar_base_q[gi])) + $bits(rbar_sh_q[gi])) + $bits(
		      rbar_xn_q[gi]));
	      localparam	FLOP_GROUP_RESET_VALUE
						= {{2 {1'b1}}, {27 {1'b1}}, {2
		      {1'b1}}, 1'b1};

	      logic
		[(FLOP_GROUP_WIDTH - 1):0]
				flop_group_gi;
	      logic
		[(FLOP_GROUP_WIDTH - 1):0]
