	assign tcm_write_o = tcm_write;
	assign tcm_priv_o = priv_buf;
	assign tcm_be_o = tcm_be;
	assign tcm_wr_data_o = (lsu_ack_last ? lsu_data_i : data_buf);
	assign itcm_trans = (target_buf == yamin_pkg::TCM_TARGET_ITCM);
	assign dtcm_trans = (target_buf == yamin_pkg::TCM_TARGET_DTCM);
	assign tcm_req[0] = ((addr_valid & dtcm_trans) & (addr_buf[3:2] ==
		2'b0));
	assign tcm_req[1] = ((addr_valid & dtcm_trans) & (addr_buf[3:2] ==
		2'b1));
	assign tcm_req[2] = ((addr_valid & dtcm_trans) & (addr_buf[3:2] ==
		2'b10));
	assign tcm_req[3] = ((addr_valid & dtcm_trans) & (addr_buf[3:2] ==
		2'b11));
