	assign rd0_req = lsu_tcu_rd0_req_i;
	assign rd1_req = lsu_tcu_rd1_req_i;
	assign wr_req = ((~lsu_tcu_wr_cancel_addr_i) & lsu_tcu_wr_req_i);
	assign req_boost = ((~(|addr_phase_end)) & (((((((((addr_valid &
		lsu_req_i) | (addr_valid & lsu_drain_i)) | (lsu_rd0_hazard &
		rd0_req)) | (lsu_rd1_hazard & rd1_req)) | (lsu_wr_hazard &
		wr_req)) | (ahbs_rd0_hazard & ahbs_rd_req_i)) | (ahbs_rd1_hazard
		& ahbs_rd_req_i)) | rmw_wr_addr_phase) | wr_age_counter_ge2));
	assign wr_age_counter_nxt = (wr_age_counter_reload ? 2'b0 :
