	assign wr_age_counter_2 = (wr_age_counter == 2'b10);
	assign wr_age_counter_3 = (wr_age_counter == 2'b11);
	assign wr_age_counter_ge2 = (wr_age_counter_2 | wr_age_counter_3);
	assign wr_age_counter_reload = trans_end;
	assign wr_age_counter_en = (wr_age_counter_reload | ((addr_valid &
		lsu_watchcat_fire_i) & (~wr_age_counter_3)));
	assign watchcat_two_o = wr_age_counter_2;
	assign watchcat_three_o = wr_age_counter_3;
	assign tcm_req_boost_o = (req_boost_q | lsu_tcu_tcm_store_in_ls2_i);
	assign tcm_wr_resp_phase_nxt = ((addr_phase_end & {5 {(~rmw_read)}}) |
		(tcm_wait_i & tcm_wr_resp_phase));
	assign tcm_wr_resp_phase_en = ((|tcm_ack_i) | (|tcm_wr_resp_phase));
	assign tcm_wr_resp_phase_end = (tcm_wr_resp_phase & (~tcm_wait_i));
	assign lsu_err = ((tcm_wr_resp_phase_end | tcm_rd_resp_phase_end) &
		tcm_err_i);
	assign itcm_err = (|lsu_err[4]);
	assign dtcm_err = (|lsu_err[3:0]);
	assign lsu_itcm_err_o = itcm_err;
	assign lsu_dtcm_err_o = dtcm_err;
	assign tcm_write = (~rmw_read);
	assign tcm_be = (be_buf & {4 {tcm_write}});
	assign lsu_rd0_hazard = hazard_chk(lsu_tcu_rd0_target_i,
		lsu_tcu_rd0_addr_i, lsu_tcu_rd0_be_i, addr_valid, target_buf,
		addr_buf[23:2], be_buf);
	assign lsu_rd1_hazard = hazard_chk(lsu_tcu_rd1_target_i,
		lsu_tcu_rd1_addr_i, lsu_tcu_rd1_be_i, addr_valid, target_buf,
		addr_buf[23:2], be_buf);
	assign ahbs_rd0_hazard = hazard_chk(ahbs_target_i, {ahbs_addr_i[23:3],
		1'b0}, ahbs_be_i[3:0], addr_valid, target_buf, addr_buf[23:2],
		be_buf);
	assign ahbs_rd1_hazard = hazard_chk(ahbs_target_i, {ahbs_addr_i[23:3],
		1'b1}, ahbs_be_i[7:4], addr_valid, target_buf, addr_buf[23:2],
		be_buf);
	assign lsu_wr_hazard = hazard_chk(lsu_tcu_wr_target_i,
		lsu_tcu_wr_addr_i, lsu_tcu_wr_be_i, addr_valid, target_buf,
		addr_buf[23:2], be_buf);
