		lsu_tcu_rd0_addr_i, 4'b1111, addr_valid, target_buf,
		addr_buf[23:2], be_buf);
	assign lsu_rd1_word_hazard = hazard_chk(lsu_tcu_rd1_target_i,
		lsu_tcu_rd1_addr_i, 4'b1111, addr_valid, target_buf,
		addr_buf[23:2], be_buf);
	assign rd0_hazard_o = lsu_rd0_hazard;
	assign rd1_hazard_o = lsu_rd1_hazard;
	assign rd0_word_hazard_o = lsu_rd0_word_hazard;
	assign rd1_word_hazard_o = lsu_rd1_word_hazard;
	assign ahbs_hazard_o = {ahbs_rd1_hazard, ahbs_rd0_hazard};
	assign lsu_wr_hazard_o = lsu_wr_hazard;

	function automatic hazard_chk;
	input logic		target;
	input logic
		[23:2]		addr;
	input logic
		[3:0]		be;
	input logic		f_valid;
	input logic		f_target;
	input logic
		[23:2]		f_addr;
	input logic
		[3:0]		f_be;
	begin
	  hazard_chk = (((f_valid & (target == f_target)) & (addr == f_addr)) &
		  (|(be & f_be)));
	end
	endfunction

	always_ff @(posedge clk or negedge reset_n) begin : sm_p
	  if (~reset_n) begin
	    addr_valid <= 1'b0;
	    lsu_ack_last <= 1'b0;
	  end
	  else
	    begin
	      addr_valid <= addr_valid_nxt;
	      lsu_ack_last <= lsu_ack;
	    end
	end
	always_ff @(posedge clk or negedge full_reset_n) begin : lsu_a_buff_p
	  if (~full_reset_n) begin
	    addr_buf <= {24 {1'b0}};
	    alias_addr_buf <= {1 {1'b0}};
	    target_buf <= {1 {1'b0}};
	    debug_buf <= {1 {1'b0}};
	    priv_buf <= {1 {1'b0}};
	    be_buf <= {4 {1'b0}};
	  end
	  else if (lsu_ack) begin
	    addr_buf <= lsu_addr_i;
	    alias_addr_buf <= lsu_alias_addr_i;
	    target_buf <= lsu_target_i;
	    debug_buf <= lsu_debug_i;
	    priv_buf <= lsu_priv_i;
	    be_buf <= lsu_be_i;
	  end
	end
	always_ff @(posedge clk or negedge full_reset_n) begin : lsu_d_buff_p
	  if (~full_reset_n) begin
	    data_buf <= {32 {1'b0}};
	  end
	  else if (load_data) begin
	    data_buf <= data_buf_nxt;
	  end
	end
	always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	  req_boost_q <= 1'b0;
	end
	else begin
	  req_boost_q <= req_boost;
	end
	always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	  wr_age_counter <= 2'b0;
	end
	else if (wr_age_counter_en) begin
	  wr_age_counter <= wr_age_counter_nxt;
	end
	always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	  tcm_wr_resp_phase <= {5 {1'b0}};
	end
	else if (tcm_wr_resp_phase_en) begin
	  tcm_wr_resp_phase <= tcm_wr_resp_phase_nxt;
	end

	if (RAR == 1) begin : gen_full_reset 

	  assign full_reset_n = reset_n;
	end
	else  begin : gen_not_full_reset 

	  assign full_reset_n = 1'b1;
	end

	if (ECC) begin : g_ecc 

	  logic	[4:0]		tcm_rd_resp_phase;
	  logic	[4:0]		tcm_rd_resp_phase_nxt;
	  logic			tcm_rd_resp_phase_en;
	  logic			rd_resp_end;
	  logic			ecc_err;
	  logic	[4:0]		tcm_ecc_err;
	  logic	[4:0]		tcm_ecc_err_q;
	  logic	[4:0]		tcm_uncorr_ecc_err;
	  logic			rmw_subchunk;
	  logic	[31:0]		tcm_rd_data;
	  logic			rmw_itcm_trans;
	  logic			rmw_dtcm_trans;
	  logic			tcm_rd_err;
	  logic			tcm_rd_tebr_poison;
	  logic			uncorr_ecc_err;
	  rmw_state_t		rmw_state;
	  rmw_state_t		rmw_state_nxt;

	  assign tcm_rd_resp_phase_nxt = ((addr_phase_end & {5 {rmw_read}}) |
		  (tcm_wait_i & tcm_rd_resp_phase));
	  assign tcm_rd_resp_phase_en = ((|tcm_ack_i) | (|tcm_rd_resp_phase));
	  assign tcm_rd_resp_phase_end = (tcm_rd_resp_phase & (~tcm_wait_i));
	  assign rd_resp_end = (|tcm_rd_resp_phase_end);
	  assign tcm_rd_err = (|(tcm_rd_resp_phase_end & tcm_err_i));
	  assign tcm_rd_tebr_poison = (|(tcm_rd_resp_phase_end &
		  tcm_tebr_rd_hit_poison_i));
	  assign tcm_ecc_err = (tcm_rd_resp_phase_end & tcm_ecc_err_i);
	  assign ecc_err = (|tcm_ecc_err);
	  assign tcm_uncorr_ecc_err = (tcm_ecc_err_q & tcm_uncorr_ecc_err_i);
	  assign uncorr_ecc_err = (|tcm_uncorr_ecc_err);
	  assign rmw_subchunk = (~(&be_buf));
	  assign rmw_itcm_trans = (itcm_trans & rmw_subchunk);
	  assign rmw_dtcm_trans = (dtcm_trans & rmw_subchunk);
	  assign rmw_trans = (((addr_valid & rmw_subchunk) & (rmw_itcm_trans |
		  rmw_dtcm_trans)) & scb_ecc_en_i);
	  assign tcm_rd_data = (((((((((({32 {tcm_rd_resp_phase[0]}} &
		  tcm_rd_data_i[0]) | ({32 {tcm_rd_resp_phase[1]}} &
		  tcm_rd_data_i[1])) | ({32 {tcm_rd_resp_phase[2]}} &
		  tcm_rd_data_i[2])) | ({32 {tcm_rd_resp_phase[3]}} &
		  tcm_rd_data_i[3])) | ({32 {tcm_rd_resp_phase[4]}} &
		  tcm_rd_data_i[4])) | ({32 {tcm_ecc_err_q[0]}} &
		  tcm_rd_data_corr_i[0])) | ({32 {tcm_ecc_err_q[1]}} &
		  tcm_rd_data_corr_i[1])) | ({32 {tcm_ecc_err_q[2]}} &
		  tcm_rd_data_corr_i[2])) | ({32 {tcm_ecc_err_q[3]}} &
		  tcm_rd_data_corr_i[3])) | ({32 {tcm_ecc_err_q[4]}} &
		  tcm_rd_data_corr_i[4]));
	  assign flop_parity_auto__tcm_rd_resp_phase = tcm_rd_resp_phase;
	  assign flop_parity_auto__rmw_state = rmw_state;
	  assign flop_parity_auto__rmw_state_nxt = rmw_state_nxt;
	  assign flop_parity_auto__tcm_rd_resp_phase_nxt = tcm_rd_resp_phase_nxt
		  ;
	  assign flop_parity_auto__tcm_ecc_err = tcm_ecc_err;
	  assign flop_parity_auto__tcm_ecc_err_q = tcm_ecc_err_q;
	  assign flop_parity_auto__tcm_rd_resp_phase_en = tcm_rd_resp_phase_en;

	  always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	    tcm_rd_resp_phase <= {5 {1'b0}};
	  end
	  else if (tcm_rd_resp_phase_en) begin
	    tcm_rd_resp_phase <= tcm_rd_resp_phase_nxt;
	  end
