	  always_comb  begin : merged_data_p

	    integer		i;
	    for (i = 0; (i < 4); i = (i + 1))
	      if (be_buf[i]) begin
		merged_data[(i * 8)+:8] = data_buf[(i * 8)+:8];
	      end
	      else begin
		merged_data[(i * 8)+:8] = tcm_rd_data[(i * 8)+:8];
	      end
