	  always_comb  begin
	    rmw_state_nxt = rmw_state;
	    rmw_merged_load = 1'b0;
	    rmw_busy = 1'b0;
	    rmw_end = 1'b0;
	    rmw_read = 1'b0;
	    rmw_rd_resp_phase = 1'b0;
	    rmw_rd_ecc_corr = 1'b0;
	    rmw_wr_addr_phase = 1'b0;
	    case (rmw_state)
	      RMW_START_ST: begin
		rmw_read = rmw_trans;
		rmw_busy = rmw_trans;
		if (rmw_trans & (|addr_phase_end)) begin
		  rmw_state_nxt = RMW_RD_RESP_ST;
		end
	      end
	      RMW_RD_RESP_ST: begin
		rmw_rd_resp_phase = 1'b1;
		rmw_busy = 1'b1;
		rmw_end = (tcm_rd_err | tcm_rd_tebr_poison);
