module yamin_ecc_generate(data_i, ecc_o);

	import yamin_ecc_pkg::*;
	parameter ecc_scheme_t	SCHEME		= yamin_ecc_pkg::ECC_SECDED_41_7
		;
	parameter		DATUM_WIDTH	= ecc_datum_width(SCHEME);
	parameter		CODE_WIDTH	= ecc_code_width(SCHEME);
	input	[(DATUM_WIDTH - 1):0]
				data_i;

	logic	[(DATUM_WIDTH - 1):0]
				data_i;
	output	[(CODE_WIDTH - 1):0]
				ecc_o;
	logic	[(CODE_WIDTH - 1):0]
				ecc_o;
	genvar 			mask_iter;

	logic	[(DATUM_WIDTH - 1):0]
				masks[(CODE_WIDTH - 1):0];
	logic	[(CODE_WIDTH - 1):0]
				odd_even;
	yamin_ecc_mask #(.SCHEME(SCHEME)) u_masks(
		.masks_o			(masks), 
		.odd_even_o			(odd_even));

	for (mask_iter = 0; (mask_iter < CODE_WIDTH); mask_iter = (mask_iter + 1
		)) begin : gen_ecc 

	  assign ecc_o[mask_iter] = ((^(data_i & masks[mask_iter])) ^
		  odd_even[mask_iter]);
	end
endmodule
`endcelldefine

