`timescale 1 ns / 1 ps
module css600_lpislave_fsm(clk, reset_n, qreq_sync_n, qaccept_n, qdeny,
	lp_request, dev_active, lp_done, dev_run, cg_en);
	input			clk;
	input			reset_n;
	input			qreq_sync_n;
	output			qaccept_n;
	output			qdeny;
	output			lp_request;

	reg			lp_request;
	input			dev_active;
	input			lp_done;
	output			dev_run;
	output			cg_en;
	reg			cg_en;
	reg	[2:0]		state;
	reg	[2:0]		next_state;
	localparam		Q_STOPPED	= 3'b0;
	localparam		Q_RUN		= 3'b101;
	localparam		Q_REQUEST	= 3'b100;
	localparam		Q_EXIT		= 3'b1;
	localparam		Q_DENY_HOLD	= 3'b111;
	localparam		Q_DENY		= 3'b110;
	localparam		UNUSED_2	= 3'b010;
	localparam		UNUSED_3	= 3'b011;
	wire			state_en = (next_state != state);

	assign dev_run = state[2];
	assign qaccept_n = state[2];
	assign qdeny = state[1];

	always @(state or qreq_sync_n or lp_done or dev_active) begin
	  next_state = state;
	  cg_en = 1'b1;
	  case (state)
	    Q_STOPPED: begin
	      cg_en = qreq_sync_n;
	      if (qreq_sync_n) begin
		if (lp_done) begin
		  next_state = Q_EXIT;
		end
		else begin
		  next_state = Q_RUN;
		end
	      end
	    end
	    Q_EXIT: begin
	      if (!lp_done) begin
		next_state = Q_RUN;
	      end
	    end
	    Q_RUN: begin
	      if (!qreq_sync_n) begin
		if (dev_active) begin
		  next_state = Q_DENY;
		end
		else if (lp_done) begin
		  next_state = Q_STOPPED;
		end
		else begin
		  next_state = Q_REQUEST;
		end
	      end
	    end
	    Q_REQUEST: begin
	      if (dev_active) begin
		if (lp_done) begin
		  next_state = Q_DENY;
		end
		else begin
		  next_state = Q_DENY_HOLD;
		end
	      end
	      else if (lp_done) begin
		next_state = Q_STOPPED;
	      end
	    end
	    Q_DENY_HOLD: begin
	      if (lp_done) begin
		next_state = Q_DENY;
	      end
	    end
	    Q_DENY: begin
	      if (qreq_sync_n && (!lp_done)) begin
		next_state = Q_RUN;
	      end
	    end
	    UNUSED_2: begin
	      next_state = Q_STOPPED;
	    end
	    UNUSED_3: begin
	      next_state = Q_STOPPED;
	    end
	    default: begin
	      next_state = 3'bxxx;
	      cg_en = 1'bx;
	    end
	  endcase
	end
	always @(state or qreq_sync_n or dev_active) begin
	  case (state)
	    Q_STOPPED:
	      lp_request = (!qreq_sync_n);
	    Q_EXIT, Q_DENY, UNUSED_2, UNUSED_3:
	      lp_request = 1'b0;
	    Q_RUN:
	      lp_request = ((!qreq_sync_n) & (!dev_active));
	    Q_REQUEST, Q_DENY_HOLD:
	      lp_request = 1'b1;
	    default:
	      lp_request = 1'bx;
	  endcase
	end
	always @(posedge clk or negedge reset_n) begin
	  if (!reset_n) begin
	    state <= Q_STOPPED;
	  end
	  else if (state_en) begin
	    state <= next_state;
	  end
	end
endmodule
