module css600_claimtags(clk, reset_n, claim_set_wr, claim_set_wr_data,
	claim_set_rd, claim_set_rd_data, claim_clr_wr, claim_clr_wr_data,
	claim_clr_rd, claim_clr_rd_data);
	parameter		NUM_CLAIM_TAGS	= 2;
	input			clk;
	input			reset_n;
	input			claim_set_wr;
	input	[(NUM_CLAIM_TAGS - 1):0]
				claim_set_wr_data;
	input			claim_set_rd;
	output	[(NUM_CLAIM_TAGS - 1):0]
				claim_set_rd_data;
	input			claim_clr_wr;
	input	[(NUM_CLAIM_TAGS - 1):0]
				claim_clr_wr_data;
	input			claim_clr_rd;
	output	[(NUM_CLAIM_TAGS - 1):0]
				claim_clr_rd_data;

	reg	[(NUM_CLAIM_TAGS - 1):0]
				claim_tags;
	reg	[(NUM_CLAIM_TAGS - 1):0]
				claim_tags_next;
	genvar 			tag;
	wire			claim_tag_en = (claim_set_wr | claim_clr_wr);

	assign claim_set_rd_data = (claim_set_rd ? {NUM_CLAIM_TAGS {1'b1}} :
		{NUM_CLAIM_TAGS {1'b0}});
	assign claim_clr_rd_data = (claim_clr_rd ? claim_tags : {NUM_CLAIM_TAGS
		{1'b0}});

	for (tag = 0; (tag < NUM_CLAIM_TAGS); tag = (tag + 1)) begin : gen_tags 

	  always @(claim_set_wr or claim_set_wr_data or claim_clr_wr or 
		  claim_clr_wr_data or claim_tags) begin
	    claim_tags_next[tag] = claim_tags[tag];
	    if (claim_set_wr && claim_set_wr_data[tag]) begin
	      claim_tags_next[tag] = 1'b1;
	    end
	    if (claim_clr_wr && claim_clr_wr_data[tag]) begin
	      claim_tags_next[tag] = 1'b0;
	    end
	  end
	  always @(posedge clk or negedge reset_n) begin
	    if (!reset_n) begin
	      claim_tags[tag] <= 1'b0;
	    end
	    else if (claim_tag_en) begin
	      claim_tags[tag] <= claim_tags_next[tag];
	    end
	  end
	end
endmodule
`endcelldefine

