module css600_cdc_capt_sync_high(clk, reset_n, d_async_i, q_sync_o);
	parameter		FF_SYNC_DEPTH	= 2;
	localparam		SYNC_DEPTH	= ((FF_SYNC_DEPTH == 3) ? 3 : 2)
		;
	input			clk;
	input			reset_n;
	input			d_async_i;
	output			q_sync_o;

	reg			d_sync1;
	reg			d_sync2;

	if (SYNC_DEPTH == 3) begin : sync_depth_3 

	  reg			d_sync3;

	  assign q_sync_o = d_sync3;

	  always @(posedge clk or negedge reset_n) begin
	    if (!reset_n) begin
	      d_sync1 <= 1'b1;
	      d_sync2 <= 1'b1;
	      d_sync3 <= 1'b1;
	    end
	    else
	      begin
		d_sync1 <= d_async_i;
		d_sync2 <= d_sync1;
		d_sync3 <= d_sync2;
	      end
	  end
	end
	else  begin : sync_depth_2 

	  assign q_sync_o = d_sync2;

	  always @(posedge clk or negedge reset_n) begin
	    if (!reset_n) begin
	      d_sync1 <= 1'b1;
	      d_sync2 <= 1'b1;
	    end
	    else
	      begin
		d_sync1 <= d_async_i;
		d_sync2 <= d_sync1;
	      end
	  end
	end
endmodule
