	    state_nxt = 3'bxxx;
	endcase
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  state <= STATE_IDLE;
	end
	else if (state != state_nxt) begin
	  state <= state_nxt;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  num_outstanding_pf <= '0;
	end
	else begin
	  num_outstanding_pf <= next_num_outstanding_pf;
	end
	always_comb  begin : next_dirty_comb
	  dirty_en = 1'b0;
	  next_dirty = 1'bx;
	  if (claim | pf_switch) begin
	    dirty_en = 1'b1;
	    next_dirty = 1'b0;
	  end
	  else if (stb_merge_grant_i & stb_biu_lf_merge_update_dirty_i) begin
	    dirty_en = 1'b1;
	    next_dirty = 1'b1;
	  end
	  else if (mbist_write_tag_mb0_i) begin
	    dirty_en = 1'b1;
	    next_dirty = mbist_wdata_no_ecc_mb0_i[23];
	  end
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  dirty <= 1'b0;
	end
	else if (dirty_en) begin
	  dirty <= next_dirty;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  addr_start <= '0;
	end
	else if (addr_start_en) begin
	  addr_start <= addr_start_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  addr_line_idx <= '0;
	end
	else if (addr_line_idx_en) begin
	  addr_line_idx <= addr_line_idx_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  addr_word_idx <= '0;
	end
	else if (addr_word_idx_en) begin
	  addr_word_idx <= addr_word_idx_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  claimed_by_lf <= '0;
	end
	else if (claimed_by_lf_en) begin
	  claimed_by_lf <= claimed_by_lf_nxt;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  claimed_by_pf <= '0;
	end
	else if (claimed_by_pf_en) begin
	  claimed_by_pf <= claimed_by_pf_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  attrs <= attr_t'('0);
	end
	else if (attrs_en) begin
	  attrs <= attrs_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  ns_attr <= '0;
	end
	else if (ns_attr_en) begin
	  ns_attr <= ns_attr_nxt;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  lfb_length <= '0;
	end
	else if (lfb_length_en) begin
	  lfb_length <= lfb_length_nxt;
	end
	always_comb  begin : next_way_comb
	  way_en = 1'b0;
	  next_way = 2'bxx;
	  if (claim & claim_is_lf_i) begin
	    way_en = 1'b1;
	    next_way = claim_way_i;
	  end
	  else if (pf_switch) begin
	    way_en = 1'b1;
	    next_way = pf_2nd_alloc_way_i;
	  end
	  else if (tag_read_req & read_has_prio_i) begin
	    way_en = 1'b1;
	    next_way = way_adj;
	  end
	  else if (maint_ecc_ev_claim_i) begin
	    way_en = 1'b1;
	    next_way = (dcu_biu_maint_ecc_ev_way_i[0] ? 2'b0 :
		    (dcu_biu_maint_ecc_ev_way_i[1] ? 2'b1 :
		    (dcu_biu_maint_ecc_ev_way_i[2] ? 2'b10 :
		    (dcu_biu_maint_ecc_ev_way_i[3] ? 2'b11 : 2'b0))));
	  end
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
