	end

	for (i = 0; (i < 32); i = (i + 1)) begin : gen_lfb_data 

	  always_comb  begin : next_data_comb
	    data_en[i] = 1'b0;
	    next_data[(i * 8)+:8] = 8'hxx;
	    if ((stb_merge_grant_i & (i[4:3] == stb_merge_dword_addr_i[4:3])) & 
