	    end
	    else if (state_entering_idle | init_data) begin
	      data_en[i] = 1'b1;
	      next_data[(i * 8)+:8] = {8 {1'b0}};
	    end
	  end
	  always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		  rar_csysreset_n) begin
	    data[(i * 8)+:8] <= {8 {1'b0}};
	  end
	  else if (data_en[i]) begin
	    data[(i * 8)+:8] <= next_data[(i * 8)+:8];
	  end
	end

	for (i = 0; (i < 4); i = (i + 1)) begin : gen_lfb_resp 

	  assign resp_en[i] = ((claim | pf_switch) | (data_in_val_qual &
		  (addr_word_idx[4:3] == i[1:0])));
	  assign next_resp[i] = ((claim | pf_switch) ? yamin_pkg::AXI_FRESP_OKAY
		  : resp_in_i);

	  always_ff @(posedge bclk or negedge rar_csysreset_n) begin
	    if (~rar_csysreset_n) begin
	      resp[i] <= yamin_pkg::AXI_FRESP_OKAY;
	    end
	    else if (resp_en[i]) begin
	      resp[i] <= next_resp[i];
	    end
	  end
	end

	for (i = 0; (i < 4); i = (i + 1)) begin : gen_dword_merged 

	  assign next_dword_merged[i] = ((stb_merge_grant_i &
		  (stb_merge_dword_addr_i == i[1:0])) &
		  (&stb_biu_lf_merge_wstrb_i));
	  assign dword_merged_en[i] = ((next_dword_merged[i] | claim) |
		  pf_switch);

	  always_ff @(posedge bclk or negedge rar_csysreset_n) begin
	    if (~rar_csysreset_n) begin
	      dword_merged[i] <= 1'b0;
	    end
	    else if (dword_merged_en[i]) begin
	      dword_merged[i] <= next_dword_merged[i];
	    end
	  end
	end

