	claim_addr_i, claim_wbuf_i, drop_i, drop_type_i, waddr_val_o, waddr0_o,
	waddr1_o, waddr2_o, waddr_ch_o, waddr_ev_o, wbuf_in_use_i,
	waddr_wbuf_idx_o, waddr_avail_nrm_o, waddr_avail_dev_o,
	waddr_ctr_nc_used_o, waddr_ctr_ch_used_o, waddr_ctr_ev_used_o,
	waddr_ctr_ch_ev_used_o, waddr_ctr_dev_used_o, waddr_last_nc_dropped_o,
	valid_wids_o, any_stores_on_axi_o, flop_parity_fault_o);

	import yamin_pkg::*;
	import yamin_biu_pkg::*;
	parameter		ICACHESZ	= 5'b01111;
	parameter		DCACHESZ	= 5'b01111;
	parameter		IDCACHEID	= 0;
	parameter		ECC		= 0;
	parameter		FPU		= 1;
	parameter		MVE		= 2;
	parameter		SECEXT		= 0;
	parameter		CPIF		= 0;
	parameter		MPU_NS		= 8;
	parameter		MPU_S		= 8;
	parameter		SAU		= 4;
	parameter		ITGU		= 0;
	parameter		DTGU		= 0;
	parameter		ITGUBLKSZ	= 6;
	parameter		DTGUBLKSZ	= 6;
	parameter		ITGUMAXBLKS	= 1;
	parameter		DTGUMAXBLKS	= 1;
	parameter		NUMIRQ		= 32;
	parameter		IRQLVL		= 3;
	parameter [479:0]	IRQTIER		= {480 {1'b0}};
	parameter [479:0]	IRQDIS		= {480 {1'b0}};
	parameter		BUSPROT		= 0;
	parameter		LOCKSTEP	= 0;
	parameter		FLOPPARITY	= 0;
	parameter		DBGLVL		= 1;
	parameter		ITM		= 0;
	parameter		ETM		= 0;
	parameter		PMC		= 0;
	parameter		PMCPROGSIZE	= 14;
	parameter		IWIC		= 0;
	parameter		WICLINES	= (NUMIRQ + 3);
	parameter		CTI		= 0;
	parameter		RAR		= 0;
	parameter		CDEMAPPEDONCP0	= 0;
	parameter		CDEMAPPEDONCP1	= 0;
	parameter		CDEMAPPEDONCP2	= 0;
	parameter		CDEMAPPEDONCP3	= 0;
	parameter		CDEMAPPEDONCP4	= 0;
	parameter		CDEMAPPEDONCP5	= 0;
	parameter		CDEMAPPEDONCP6	= 0;
	parameter		CDEMAPPEDONCP7	= 0;
	parameter		CDERTLID	= 0;
	parameter		ICACHE		= int'(ICACHESZ[0]);
	parameter		DCACHE		= int'(DCACHESZ[0]);
	parameter		CDE		= (((((((CDEMAPPEDONCP0 | 
		CDEMAPPEDONCP1) | CDEMAPPEDONCP2) | CDEMAPPEDONCP3) | 
		CDEMAPPEDONCP4) | CDEMAPPEDONCP5) | CDEMAPPEDONCP6) | 
		CDEMAPPEDONCP7);
	parameter [7:0]		CDE_MAP		= {(CDEMAPPEDONCP7 != 0),
		(CDEMAPPEDONCP6 != 0), (CDEMAPPEDONCP5 != 0), (CDEMAPPEDONCP4 !=
		0), (CDEMAPPEDONCP3 != 0), (CDEMAPPEDONCP2 != 0),
		(CDEMAPPEDONCP1 != 0), (CDEMAPPEDONCP0 != 0)};
	input			clk;
	input			bclk;
	input			csysreset_n;
	input			claim_i;
	input			claim_type_i;

	wire waddr_type_t	claim_type_i;
	input	[31:5]		claim_addr_i;
	input			claim_wbuf_i;
	input			drop_i;
	input			drop_type_i;
	wire waddr_type_t	drop_type_i;
	output	[2:0]		waddr_val_o;
	output	[31:5]		waddr0_o;
	output	[31:5]		waddr1_o;
	output	[31:5]		waddr2_o;
	output	[2:0]		waddr_ch_o;
	output	[2:0]		waddr_ev_o;
	input			wbuf_in_use_i;
	output	[2:0]		waddr_wbuf_idx_o;
	output			waddr_avail_nrm_o;
	output			waddr_avail_dev_o;
	output			waddr_ctr_nc_used_o;
	output			waddr_ctr_ch_used_o;
	output			waddr_ctr_ev_used_o;
	output			waddr_ctr_ch_ev_used_o;
	output			waddr_ctr_dev_used_o;
	output			waddr_last_nc_dropped_o;
	output	[3:0]		valid_wids_o;
	output			any_stores_on_axi_o;
	output			flop_parity_fault_o;
	wire			rar_csysreset_n = ((RAR == 1) ? csysreset_n : 
		1'b1);
	wire			waddr_ctr_nc_used;
	wire			waddr_ctr_ch_used;
	wire			waddr_ctr_ev_used;
	wire			waddr_ctr_ch_ev_used = (waddr_ctr_ch_used | 
		waddr_ctr_ev_used);
	wire			waddr_ctr_dev_used;
	wire	[3:0]		valid_wids;
	reg	[2:0]		waddr_val;
	wire	[2:0]		waddr_en;
	reg	[31:5]		waddr0;
	reg	[31:5]		waddr1;
	reg	[31:5]		waddr2;
	reg	[2:0]		waddr_ch;
	reg	[2:0]		waddr_ev;
	logic			nxt_waddr_ch;
	logic			nxt_waddr_ev;
	wire	[2:0]		waddr_nc = ((~waddr_ch) & (~waddr_ev));
	reg	[2:0]		waddr_wbuf_idx;
	reg	[1:0]		waddr0_older;
	reg	[1:0]		waddr1_older;
	reg	[1:0]		waddr2_older;
	logic	[1:0]		nxt_waddr0_older;
	logic	[1:0]		nxt_waddr1_older;
	logic	[1:0]		nxt_waddr2_older;
	logic			waddr_older_en;
	wire	[2:0]		waddr_val_ch;
	wire	[2:0]		waddr_val_nc;
	wire	[2:0]		waddr_val_ev;
	wire	[2:0]		waddr_oldest_ch;
	wire	[2:0]		waddr_oldest_nc;
	wire	[2:0]		waddr_oldest_ev;
	reg	[(WADDR_CTR_NC_W - 1):0]
				waddr_ctr_nc;
	logic	[(WADDR_CTR_NC_W - 1):0]
				nxt_waddr_ctr_nc;
	logic			waddr_ctr_nc_en;
	reg	[(WADDR_CTR_CH_W - 1):0]
				waddr_ctr_ch;
	logic	[(WADDR_CTR_CH_W - 1):0]
				nxt_waddr_ctr_ch;
	logic			waddr_ctr_ch_en;
	reg	[(WADDR_CTR_DEV_W - 1):0]
				waddr_ctr_dev;
	logic	[(WADDR_CTR_DEV_W - 1):0]
				nxt_waddr_ctr_dev;
	logic			waddr_ctr_dev_en;
	wire	[(WADDR_CTR_EV_W - 1):0]
				waddr_ctr_ev;
	logic	[(WADDR_CTR_EV_W - 1):0]
				nxt_waddr_ctr_ev;
	logic			waddr_ctr_ev_en;
	wire	[(WADDR_CTR_NC_W - 1):0]
				mutation_waddr_max_nc;
	wire	[(WADDR_CTR_CH_W - 1):0]
				mutation_waddr_max_ch;
	wire	[(WADDR_CTR_DEV_W - 1):0]
				mutation_waddr_max_dev;
	wire	[(WADDR_CTR_EV_W - 1):0]
				mutation_waddr_max_ev;
	wire			waddr_ch_max = ((&waddr_ctr_ch) | (waddr_ctr_ch 
		== mutation_waddr_max_ch));
	wire			waddr_ev_max = ((&waddr_ctr_ev) | (waddr_ctr_ev 
		== mutation_waddr_max_ev));
	wire			waddr_nc_max = ((&waddr_ctr_nc) | (waddr_ctr_nc 
		== mutation_waddr_max_nc));
	wire			waddr_dev_max = ((&waddr_ctr_dev) | (
		waddr_ctr_dev == mutation_waddr_max_dev));
	wire	[2:0]		waddr_evictable = ((waddr_val & (((waddr_ch & {3
		{(~waddr_ch_max)}}) | (waddr_ev & {3 {(~waddr_ev_max)}})) | (
		waddr_nc & {3 {(~waddr_nc_max)}}))) & (~({3 {wbuf_in_use_i}} & 
		waddr_wbuf_idx)));
	wire	[2:0]		waddr_oldest_evictable = (waddr_evictable & 
		{(~(|(waddr2_older & {waddr_evictable[1],
		waddr_evictable[0]}))), (~(|(waddr1_older & {waddr_evictable[2],
		waddr_evictable[0]}))), (~(|(waddr0_older & {waddr_evictable[2],
		waddr_evictable[1]})))});
	wire	[2:0]		waddr_disable;
	logic			waddr_val_en;
	wire	[2:0]		nxt_waddr_val;
	wire			waddr_avail_nrm = ((~(&waddr_val)) | (|
		waddr_evictable));
	wire			waddr_avail_dev = (~waddr_dev_max);
	wire			waddr_ctr_nc_inc = (((claim_i & (&waddr_val)) & 
		(claim_type_i != yamin_biu_pkg::WADDR_TYPE_DEV)) & ((~(
		waddr_disable == waddr_en)) & (|(waddr_oldest_evictable & 
		waddr_nc))));
	wire			waddr_ctr_ch_inc = (((claim_i & (&waddr_val)) & 
		(claim_type_i != yamin_biu_pkg::WADDR_TYPE_DEV)) & ((~(
		waddr_disable == waddr_en)) & (|(waddr_oldest_evictable & 
		waddr_ch))));
	wire			waddr_ctr_ev_inc = (((claim_i & (&waddr_val)) & 
		(claim_type_i != yamin_biu_pkg::WADDR_TYPE_DEV)) & ((~(
		waddr_disable == waddr_en)) & (|(waddr_oldest_evictable & 
		waddr_ev))));
	wire			waddr_ctr_dev_inc = (claim_i & (claim_type_i == 
		yamin_biu_pkg::WADDR_TYPE_DEV));
	wire			waddr_ctr_nc_dec = ((drop_i & waddr_ctr_nc_used)
		& (drop_type_i == yamin_biu_pkg::WADDR_TYPE_NC));
	wire			waddr_ctr_ch_dec = ((drop_i & waddr_ctr_ch_used)
		& (drop_type_i == yamin_biu_pkg::WADDR_TYPE_CH));
	wire			waddr_ctr_dev_dec = ((drop_i & 
		waddr_ctr_dev_used) & (drop_type_i == 
		yamin_biu_pkg::WADDR_TYPE_DEV));
	wire			waddr_ctr_ev_dec = ((drop_i & waddr_ctr_ev_used)
		& (drop_type_i == yamin_biu_pkg::WADDR_TYPE_EV));
	logic	[(WADDR_CTR_EV_W - 1):0]
				flop_parity_auto__waddr_ctr_ev_q;
	wire			one_valid_store_wid = (((((({{WADDR_CTR_DEV_W
		{1'b0}}, (waddr_val[0] & (~waddr_ev[0]))} + {{WADDR_CTR_DEV_W
		{1'b0}}, (waddr_val[1] & (~waddr_ev[1]))}) + {{WADDR_CTR_DEV_W
		{1'b0}}, (waddr_val[2] & (~waddr_ev[2]))}) + {1'b0,
		waddr_ctr_dev}) + {2'b0, waddr_ctr_ch}) + {2'b0, waddr_ctr_nc}) 
		== {{WADDR_CTR_DEV_W {1'b0}}, 1'b1});
	logic			any_stores_on_axi;
	logic			any_stores_on_axi_en;
	logic			nxt_any_stores_on_axi;
	wire			unused_clk = clk;

	assign waddr_en = ({3 {(claim_i & (claim_type_i !=
		yamin_biu_pkg::WADDR_TYPE_DEV))}} & ((&waddr_val) ?
		waddr_oldest_evictable : ((~waddr_val[0]) ? 3'b1 :
		((~waddr_val[1]) ? 3'b010 : 3'b100))));
	assign waddr_disable = ((drop_type_i == yamin_biu_pkg::WADDR_TYPE_CH) ?
		({3 {(drop_i & (~waddr_ctr_ch_used))}} & waddr_oldest_ch) :
		((drop_type_i == yamin_biu_pkg::WADDR_TYPE_NC) ? ({3 {(drop_i &
		(~waddr_ctr_nc_used))}} & waddr_oldest_nc) : ((drop_type_i ==
		yamin_biu_pkg::WADDR_TYPE_EV) ? ({3 {(drop_i &
		(~waddr_ctr_ev_used))}} & waddr_oldest_ev) : 3'b0)));
	assign waddr_val_en = ((|waddr_en) | drop_i);
	assign nxt_waddr_val = ((waddr_val & (~waddr_disable)) | waddr_en);
	assign nxt_waddr_ch = (claim_type_i == yamin_biu_pkg::WADDR_TYPE_CH);
	assign nxt_waddr_ev = (claim_type_i == yamin_biu_pkg::WADDR_TYPE_EV);
	assign waddr_val_ch = (waddr_val & waddr_ch);
	assign waddr_val_nc = (waddr_val & waddr_nc);
	assign waddr_val_ev = (waddr_val & waddr_ev);
	assign waddr_oldest_ch = (waddr_val_ch & {(~(|(waddr2_older &
		{waddr_val_ch[1], waddr_val_ch[0]}))), (~(|(waddr1_older &
		{waddr_val_ch[2], waddr_val_ch[0]}))), (~(|(waddr0_older &
		{waddr_val_ch[2], waddr_val_ch[1]})))});
	assign waddr_oldest_nc = (waddr_val_nc & {(~(|(waddr2_older &
		{waddr_val_nc[1], waddr_val_nc[0]}))), (~(|(waddr1_older &
		{waddr_val_nc[2], waddr_val_nc[0]}))), (~(|(waddr0_older &
		{waddr_val_nc[2], waddr_val_nc[1]})))});
	assign waddr_oldest_ev = (waddr_val_ev & {(~(|(waddr2_older &
		{waddr_val_ev[1], waddr_val_ev[0]}))), (~(|(waddr1_older &
		{waddr_val_ev[2], waddr_val_ev[0]}))), (~(|(waddr0_older &
		{waddr_val_ev[2], waddr_val_ev[1]})))});
	assign waddr_ctr_nc_en = (((waddr_ctr_nc_inc & waddr_ctr_nc_dec) |
		waddr_ctr_nc_inc) | waddr_ctr_nc_dec);
	assign nxt_waddr_ctr_nc = ((waddr_ctr_nc_inc & waddr_ctr_nc_dec) ?
		waddr_ctr_nc : (waddr_ctr_nc_inc ? (waddr_ctr_nc +
		{{(WADDR_CTR_NC_W - 1) {1'b0}}, 1'b1}) : (waddr_ctr_nc_dec ?
		(waddr_ctr_nc - {{(WADDR_CTR_NC_W - 1) {1'b0}}, 1'b1}) : 'x)));
	assign waddr_ctr_dev_en = (((waddr_ctr_dev_inc & waddr_ctr_dev_dec) |
		waddr_ctr_dev_inc) | waddr_ctr_dev_dec);
	assign nxt_waddr_ctr_dev = ((waddr_ctr_dev_inc & waddr_ctr_dev_dec) ?
		waddr_ctr_dev : (waddr_ctr_dev_inc ? (waddr_ctr_dev +
		{{(WADDR_CTR_DEV_W - 1) {1'b0}}, 1'b1}) : (waddr_ctr_dev_dec ?
		(waddr_ctr_dev - {{(WADDR_CTR_DEV_W - 1) {1'b0}}, 1'b1}) : 'x)))
		;
	assign waddr_ctr_ch_en = (((waddr_ctr_ch_inc & waddr_ctr_ch_dec) |
		waddr_ctr_ch_inc) | waddr_ctr_ch_dec);
	assign nxt_waddr_ctr_ch = ((waddr_ctr_ch_inc & waddr_ctr_ch_dec) ?
		waddr_ctr_ch : (waddr_ctr_ch_inc ? (waddr_ctr_ch +
		{{(WADDR_CTR_CH_W - 1) {1'b0}}, 1'b1}) : (waddr_ctr_ch_dec ?
		(waddr_ctr_ch - {{(WADDR_CTR_CH_W - 1) {1'b0}}, 1'b1}) : 'x)));
	assign waddr_ctr_nc_used = (|waddr_ctr_nc);
	assign waddr_ctr_ch_used = (|waddr_ctr_ch);
	assign waddr_ctr_dev_used = (|waddr_ctr_dev);
	assign waddr_ctr_ev_used = (|waddr_ctr_ev);
	assign valid_wids = {((|(waddr_val & waddr_ev)) | waddr_ctr_ev_used),
		waddr_ctr_dev_used, ((|(waddr_val & waddr_ch)) |
		waddr_ctr_ch_used), ((|(waddr_val & waddr_nc)) |
		waddr_ctr_nc_used)};
	assign mutation_waddr_max_ch = {WADDR_CTR_CH_W {1'b1}};
	assign mutation_waddr_max_ev = {WADDR_CTR_EV_W {1'b1}};
	assign mutation_waddr_max_nc = {WADDR_CTR_NC_W {1'b1}};
	assign mutation_waddr_max_dev = {WADDR_CTR_DEV_W {1'b1}};
	assign waddr_val_o = waddr_val;
	assign waddr0_o = waddr0;
	assign waddr1_o = waddr1;
	assign waddr2_o = waddr2;
	assign waddr_ch_o = waddr_ch;
	assign waddr_ev_o = waddr_ev;
	assign waddr_wbuf_idx_o = waddr_wbuf_idx;
	assign waddr_avail_nrm_o = waddr_avail_nrm;
	assign waddr_avail_dev_o = waddr_avail_dev;
	assign waddr_ctr_nc_used_o = waddr_ctr_nc_used;
	assign waddr_ctr_ch_used_o = waddr_ctr_ch_used;
	assign waddr_ctr_ev_used_o = waddr_ctr_ev_used;
	assign waddr_ctr_ch_ev_used_o = waddr_ctr_ch_ev_used;
	assign waddr_ctr_dev_used_o = waddr_ctr_dev_used;
	assign waddr_last_nc_dropped_o = ((drop_i & (drop_type_i ==
		yamin_biu_pkg::WADDR_TYPE_NC)) & (((({{WADDR_CTR_NC_W {1'b0}},
		waddr_val_nc[0]} + {{WADDR_CTR_NC_W {1'b0}}, waddr_val_nc[1]}) +
		{{WADDR_CTR_NC_W {1'b0}}, waddr_val_nc[2]}) + {1'b0,
		waddr_ctr_nc}) == {{WADDR_CTR_NC_W {1'b0}}, 1'b1}));
	assign valid_wids_o = valid_wids;
	assign any_stores_on_axi_en = ((claim_i & (claim_type_i !=
		yamin_biu_pkg::WADDR_TYPE_EV)) | (drop_i & (drop_type_i !=
		yamin_biu_pkg::WADDR_TYPE_EV)));
	assign nxt_any_stores_on_axi = ((claim_i & (claim_type_i !=
		yamin_biu_pkg::WADDR_TYPE_EV)) ? 1'b1 : ((drop_i & (drop_type_i
		!= yamin_biu_pkg::WADDR_TYPE_EV)) ? (~one_valid_store_wid) :
		1'bx));
	assign any_stores_on_axi_o = any_stores_on_axi;

	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  waddr_val <= 3'b0;
	end
	else if (waddr_val_en) begin
	  waddr_val <= nxt_waddr_val;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  waddr0 <= {27 {1'b0}};
	  waddr_ch[0] <= 1'b0;
	  waddr_ev[0] <= 1'b0;
	end
	else if (waddr_en[0]) begin
	  waddr0 <= claim_addr_i;
	  waddr_ch[0] <= nxt_waddr_ch;
	  waddr_ev[0] <= nxt_waddr_ev;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  waddr1 <= {27 {1'b0}};
	  waddr_ch[1] <= 1'b0;
	  waddr_ev[1] <= 1'b0;
	end
	else if (waddr_en[1]) begin
	  waddr1 <= claim_addr_i;
	  waddr_ch[1] <= nxt_waddr_ch;
	  waddr_ev[1] <= nxt_waddr_ev;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  waddr2 <= {27 {1'b0}};
	  waddr_ch[2] <= 1'b0;
	  waddr_ev[2] <= 1'b0;
	end
	else if (waddr_en[2]) begin
	  waddr2 <= claim_addr_i;
	  waddr_ch[2] <= nxt_waddr_ch;
	  waddr_ev[2] <= nxt_waddr_ev;
	end
	always_comb  begin : nxt_waddr_older_comb
	  waddr_older_en = 1'b0;
	  nxt_waddr0_older = 2'bxx;
	  nxt_waddr1_older = 2'bxx;
	  nxt_waddr2_older = 2'bxx;
	  if (waddr_en[0]) begin
	    waddr_older_en = 1'b1;
	    nxt_waddr0_older = 2'b11;
	    nxt_waddr1_older = {waddr1_older[1], 1'b0};
	    nxt_waddr2_older = {waddr2_older[1], 1'b0};
	  end
	  else if (waddr_en[1]) begin
	    waddr_older_en = 1'b1;
	    nxt_waddr1_older = 2'b11;
	    nxt_waddr0_older = {waddr0_older[1], 1'b0};
	    nxt_waddr2_older = {1'b0, waddr2_older[0]};
	  end
	  else if (waddr_en[2]) begin
	    waddr_older_en = 1'b1;
	    nxt_waddr2_older = 2'b11;
	    nxt_waddr0_older = {1'b0, waddr0_older[0]};
	    nxt_waddr1_older = {1'b0, waddr1_older[0]};
	  end
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  waddr0_older <= 2'b0;
	  waddr1_older <= 2'b0;
	  waddr2_older <= 2'b0;
	end
	else if (waddr_older_en) begin
	  waddr0_older <= nxt_waddr0_older;
	  waddr1_older <= nxt_waddr1_older;
	  waddr2_older <= nxt_waddr2_older;
	end
	always_ff @(posedge bclk or negedge rar_csysreset_n) if (~
		rar_csysreset_n) begin
	  waddr_wbuf_idx <= {3 {1'b0}};
	end
	else if (claim_wbuf_i) begin
	  waddr_wbuf_idx <= waddr_en;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  waddr_ctr_nc <= {WADDR_CTR_NC_W {1'b0}};
	end
	else if (waddr_ctr_nc_en) begin
	  waddr_ctr_nc <= nxt_waddr_ctr_nc;
	end
	always_ff @(posedge bclk or negedge csysreset_n) if (~csysreset_n) begin
	  waddr_ctr_dev <= {WADDR_CTR_DEV_W {1'b0}};
	end
	else if (waddr_ctr_dev_en) begin
