	parameter		IDCACHEID	= 0;
	parameter		ECC		= 0;
	parameter		FPU		= 1;
	parameter		MVE		= 2;
	parameter		SECEXT		= 0;
	parameter		CPIF		= 0;
	parameter		MPU_NS		= 8;
	parameter		MPU_S		= 8;
	parameter		SAU		= 4;
	parameter		ITGU		= 0;
	parameter		DTGU		= 0;
	parameter		ITGUBLKSZ	= 6;
	parameter		DTGUBLKSZ	= 6;
	parameter		ITGUMAXBLKS	= 1;
	parameter		DTGUMAXBLKS	= 1;
	parameter		NUMIRQ		= 32;
	parameter		IRQLVL		= 3;
	parameter [479:0]	IRQTIER		= {480 {1'b0}};
	parameter [479:0]	IRQDIS		= {480 {1'b0}};
	parameter		BUSPROT		= 0;
	parameter		LOCKSTEP	= 0;
	parameter		FLOPPARITY	= 0;
	parameter		DBGLVL		= 1;
	parameter		ITM		= 0;
	parameter		ETM		= 0;
	parameter		PMC		= 0;
	parameter		PMCPROGSIZE	= 14;
	parameter		IWIC		= 0;
	parameter		WICLINES	= (NUMIRQ + 3);
	parameter		CTI		= 0;
	parameter		RAR		= 0;
	parameter		CDEMAPPEDONCP0	= 0;
	parameter		CDEMAPPEDONCP1	= 0;
	parameter		CDEMAPPEDONCP2	= 0;
	parameter		CDEMAPPEDONCP3	= 0;
	parameter		CDEMAPPEDONCP4	= 0;
	parameter		CDEMAPPEDONCP5	= 0;
	parameter		CDEMAPPEDONCP6	= 0;
	parameter		CDEMAPPEDONCP7	= 0;
	parameter		CDERTLID	= 0;
	parameter		ICACHE		= int'(ICACHESZ[0]);
	parameter		DCACHE		= int'(DCACHESZ[0]);
	parameter		CDE		= (((((((CDEMAPPEDONCP0 | 
		CDEMAPPEDONCP1) | CDEMAPPEDONCP2) | CDEMAPPEDONCP3) | 
		CDEMAPPEDONCP4) | CDEMAPPEDONCP5) | CDEMAPPEDONCP6) | 
		CDEMAPPEDONCP7);
	parameter [7:0]		CDE_MAP		= {(CDEMAPPEDONCP7 != 0),
		(CDEMAPPEDONCP6 != 0), (CDEMAPPEDONCP5 != 0), (CDEMAPPEDONCP4 !=
		0), (CDEMAPPEDONCP3 != 0), (CDEMAPPEDONCP2 != 0),
		(CDEMAPPEDONCP1 != 0), (CDEMAPPEDONCP0 != 0)};
	input			fclk;
	input			clk;
	input			reset_n;
	input			core_nvic_int_entry_i;
	input			core_nvic_int_exit_i;
	input	[(NUM_INTERRUPTS - 1):0]
				int_actv_clr_i;
	input	[(NUM_INTERRUPTS - 1):0]
				int_actv_set_i;
	input	[(NUM_INTERRUPTS - 1):0]
				int_pend_clr_i;
	input	[(NUM_INTERRUPTS - 1):0]
				int_pend_set_i;
	input	[(NUM_INTERRUPTS - 1):0]
				int_pend_src_i;
	input	[(NUM_INTERRUPTS - 1):0]
				isr_entry_i;
	input	[(NUM_INTERRUPTS - 1):0]
				isr_exit_i;
	input	[(NUM_INTERRUPTS - 1):0]
				sevonpend_itns_sel_i;
	input	[(IRQMAX - 1):0]
				cfg_irqlatency_regd_v_i;
	output	[(NUM_INTERRUPTS - 1):0]
				int_actv_state_o;
	output	[(NUM_INTERRUPTS - 1):0]
				int_pend_state_o;
	output			nvic_core_int_resolving_o;
	output			nvic_core_int_sev_o;
	output			flop_parity_fault_o;
	localparam		NVIC_ST_IDLE	= 2'b0;
	localparam		NVIC_ST_PEND	= 2'b1;
	localparam		NVIC_ST_ACTIVE	= 2'b10;
	localparam		NVIC_ST_PEND_ACTIVE
						= 2'b11;
	localparam		NON_NUMIRQ_NS	= 5'h09;
	localparam		NUM_SYNC_EXCEP	= (SECEXT ? NON_NUMIRQ_S : 
		NON_NUMIRQ_NS);
	localparam		NUM_PEND_ACTIVE	= (NUM_SYNC_EXCEP + NUMIRQ);

	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_actv_clr_final;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_actv_set_final;
	wire			actv_state_we;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				actv_state_masked;
	wire	[(NUM_INTERRUPTS - 1):0]
				actv_state;
	reg	[(NUM_PEND_ACTIVE - 1):0]
				actv_state_nxt;
	reg	[(NUM_PEND_ACTIVE - 1):0]
				actv_state_q;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_pend_clr_final;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_pend_set_final;
	wire			pend_state_we;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				pend_state_masked;
	wire	[(NUM_INTERRUPTS - 1):0]
				pend_state;
	reg	[(NUM_INTERRUPTS - 1):0]
				pend_state_nxt;
	reg	[(NUM_PEND_ACTIVE - 1):0]
				masked_pend_state_nxt;
	reg	[(NUM_PEND_ACTIVE - 1):0]
				pend_state_q;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_isr_entry_final;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_isr_exit_final;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_pend_src_final;
	wire	[(NUM_PEND_ACTIVE - 1):0]
				int_pend_pulse;
	reg			nmi_pend_q;
	reg	[(NUMIRQ - 1):0]
				opt_irq_pend_q;
	wire	[(NUMIRQ - 1):0]
				irq_pend;
	wire			irq_pend_we;
	wire			newly_pended;
	wire			int_sev_we;
	reg			int_sev;
	integer			irq_intg;
	genvar 			i;
	genvar 			j;
	wire			int_resolving_nxt;
	wire			int_resolving_we;
	reg			int_resolving_q;
	wire			regd_irq_resolving_nxt;
	wire			regd_irq_resolving_we;
	reg			regd_irq_resolving_q;
	wire			regd_irq_resolving_d1_we;
	reg			regd_irq_resolving_d1_q;

	assign irq_pend_we = (irq_pend != int_pend_src_final[(NUM_PEND_ACTIVE -
		1):NUM_SYNC_EXCEP]);
	assign int_pend_pulse[NVIC_NMINUM] = (int_pend_src_final[NVIC_NMINUM] &
		(~nmi_pend_q));
	assign int_pend_pulse[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] = 
		(int_pend_src_final[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] &
		(~irq_pend));
	assign pend_state_we = ((((core_nvic_int_entry_i |
		(|int_pend_src_final)) | (|int_pend_pulse)) |
		(|int_pend_clr_final)) | (|int_pend_set_final));
	assign actv_state_we = (((core_nvic_int_entry_i | core_nvic_int_exit_i)
		| (|int_actv_set_final)) | (|int_actv_clr_final));
	assign pend_state_masked[(NUM_SYNC_EXCEP - 1):0] = 
		pend_state_q[(NUM_SYNC_EXCEP - 1):0];
	assign actv_state_masked[(NUM_SYNC_EXCEP - 1):0] = 
		actv_state_q[(NUM_SYNC_EXCEP - 1):0];
	assign newly_pended = (|((pend_state_nxt & (~pend_state)) &
		sevonpend_itns_sel_i));
	assign int_sev_we = (newly_pended | int_sev);
	assign int_resolving_we = (int_resolving_nxt | int_resolving_q);
	assign regd_irq_resolving_nxt = (|(cfg_irqlatency_regd_v_i[(NUMIRQ -
		1):0] & int_pend_pulse[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP]));
	assign regd_irq_resolving_we = (regd_irq_resolving_nxt |
		regd_irq_resolving_q);
	assign regd_irq_resolving_d1_we = (regd_irq_resolving_q |
		regd_irq_resolving_d1_q);
	assign int_pend_state_o = pend_state;
	assign int_actv_state_o = actv_state;
	assign nvic_core_int_sev_o = int_sev;
	assign nvic_core_int_resolving_o = (regd_irq_resolving_d1_q |
		int_resolving_q);

	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  nmi_pend_q <= 1'b0;
	end
	else begin
	  nmi_pend_q <= int_pend_src_final[NVIC_NMINUM];
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  opt_irq_pend_q[(NUMIRQ - 1):0] <= {NUMIRQ {1'b0}};
	end
	else if (irq_pend_we) begin
	  opt_irq_pend_q[(NUMIRQ - 1):0] <= ((~IRQDIS[(NUMIRQ - 1):0]) &
		  int_pend_src_final[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP]);
	end
	always_comb  for (irq_intg = 0; (irq_intg < NUM_PEND_ACTIVE); irq_intg =
		(irq_intg + 1)) begin
	  case ({actv_state_masked[irq_intg], pend_state_masked[irq_intg]})
	    NVIC_ST_IDLE: begin
	      masked_pend_state_nxt[irq_intg] = (int_pend_set_final[irq_intg] |
		      int_pend_src_final[irq_intg]);
	      actv_state_nxt[irq_intg] = (int_isr_entry_final[irq_intg] |
		      int_actv_set_final[irq_intg]);
	    end
	    NVIC_ST_PEND: begin
	      masked_pend_state_nxt[irq_intg] = (~(int_isr_entry_final[irq_intg]
		      | int_pend_clr_final[irq_intg]));
	      actv_state_nxt[irq_intg] = (int_isr_entry_final[irq_intg] |
		      int_actv_set_final[irq_intg]);
	    end
	    NVIC_ST_ACTIVE: begin
	      masked_pend_state_nxt[irq_intg] = (int_pend_pulse[irq_intg] |
		      int_pend_set_final[irq_intg]);
	      actv_state_nxt[irq_intg] = (~(int_isr_exit_final[irq_intg] |
		      int_actv_clr_final[irq_intg]));
	    end
	    NVIC_ST_PEND_ACTIVE: begin
	      masked_pend_state_nxt[irq_intg] = (~int_pend_clr_final[irq_intg]);
	      actv_state_nxt[irq_intg] = (~(int_isr_exit_final[irq_intg] |
		      int_actv_clr_final[irq_intg]));
	    end
	    default: begin
	      masked_pend_state_nxt[irq_intg] = 1'bx;
	      actv_state_nxt[irq_intg] = 1'bx;
	    end
	  endcase
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  pend_state_q[(NUM_SYNC_EXCEP - 1):0] <= {NUM_SYNC_EXCEP {1'b0}};
	end
	else if (pend_state_we) begin
	  pend_state_q[(NUM_SYNC_EXCEP - 1):0] <= 
		  masked_pend_state_nxt[(NUM_SYNC_EXCEP - 1):0];
	end
	always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	  actv_state_q[(NUM_SYNC_EXCEP - 1):0] <= {NUM_SYNC_EXCEP {1'b0}};
	end
	else if (actv_state_we) begin
	  actv_state_q[(NUM_SYNC_EXCEP - 1):0] <= actv_state_nxt[(NUM_SYNC_EXCEP
		  - 1):0];
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  pend_state_q[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] <= {NUMIRQ {1'b0}};
	end
	else if (pend_state_we) begin
	  pend_state_q[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] <= 
		  ((~IRQDIS[(NUMIRQ - 1):0]) &
		  masked_pend_state_nxt[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP]);
	end
	always_ff @(posedge clk or negedge reset_n) if (~reset_n) begin
	  actv_state_q[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] <= {NUMIRQ {1'b0}};
	end
	else if (actv_state_we) begin
	  actv_state_q[(NUM_PEND_ACTIVE - 1):NUM_SYNC_EXCEP] <= 
		  ((~IRQDIS[(NUMIRQ - 1):0]) & actv_state_nxt[(NUM_PEND_ACTIVE -
		  1):NUM_SYNC_EXCEP]);
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  int_sev <= 1'b0;
	end
	else if (int_sev_we) begin
	  int_sev <= newly_pended;
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  int_resolving_q <= 1'b0;
	end
	else if (int_resolving_we) begin
	  int_resolving_q <= int_resolving_nxt;
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  regd_irq_resolving_q <= 1'b0;
	end
	else if (regd_irq_resolving_we) begin
	  regd_irq_resolving_q <= regd_irq_resolving_nxt;
	end
	always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	  regd_irq_resolving_d1_q <= 1'b0;
	end
	else if (regd_irq_resolving_d1_we) begin
	  regd_irq_resolving_d1_q <= regd_irq_resolving_q;
	end

	if (SECEXT != 0) begin : g_s_pulse 

	  assign int_actv_clr_final = int_actv_clr_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_actv_set_final = int_actv_set_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_pend_clr_final = int_pend_clr_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_pend_set_final = int_pend_set_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_isr_entry_final = isr_entry_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_isr_exit_final = isr_exit_i[(NUM_PEND_ACTIVE - 1):0];
	  assign int_pend_src_final = int_pend_src_i[(NUM_PEND_ACTIVE - 1):0];
	end
	else  begin : g_ns_pulse 

	  assign int_actv_clr_final = {int_actv_clr_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], int_actv_clr_i[NVIC_STNUM_NS],
		  int_actv_clr_i[NVIC_PSVNUM_NS],
		  int_actv_clr_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  int_actv_clr_i[NVIC_UFNUM_NS],
		  int_actv_clr_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  int_actv_clr_i[NVIC_HFNUM_NS], int_actv_clr_i[NVIC_NMINUM]};
	  assign int_actv_set_final = {int_actv_set_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], int_actv_set_i[NVIC_STNUM_NS],
		  int_actv_set_i[NVIC_PSVNUM_NS],
		  int_actv_set_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  int_actv_set_i[NVIC_UFNUM_NS],
		  int_actv_set_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  int_actv_set_i[NVIC_HFNUM_NS], int_actv_set_i[NVIC_NMINUM]};
	  assign int_pend_clr_final = {int_pend_clr_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], int_pend_clr_i[NVIC_STNUM_NS],
		  int_pend_clr_i[NVIC_PSVNUM_NS],
		  int_pend_clr_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  int_pend_clr_i[NVIC_UFNUM_NS],
		  int_pend_clr_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  int_pend_clr_i[NVIC_HFNUM_NS], int_pend_clr_i[NVIC_NMINUM]};
	  assign int_pend_set_final = {int_pend_set_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], int_pend_set_i[NVIC_STNUM_NS],
		  int_pend_set_i[NVIC_PSVNUM_NS],
		  int_pend_set_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  int_pend_set_i[NVIC_UFNUM_NS],
		  int_pend_set_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  int_pend_set_i[NVIC_HFNUM_NS], int_pend_set_i[NVIC_NMINUM]};
	  assign int_isr_entry_final = {isr_entry_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], isr_entry_i[NVIC_STNUM_NS],
		  isr_entry_i[NVIC_PSVNUM_NS],
		  isr_entry_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  isr_entry_i[NVIC_UFNUM_NS],
		  isr_entry_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  isr_entry_i[NVIC_HFNUM_NS], isr_entry_i[NVIC_NMINUM]};
	  assign int_isr_exit_final = {isr_exit_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], isr_exit_i[NVIC_STNUM_NS],
		  isr_exit_i[NVIC_PSVNUM_NS],
		  isr_exit_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  isr_exit_i[NVIC_UFNUM_NS],
		  isr_exit_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  isr_exit_i[NVIC_HFNUM_NS], isr_exit_i[NVIC_NMINUM]};
	  assign int_pend_src_final = {int_pend_src_i[((NON_NUMIRQ_S + NUMIRQ) -
		  1):NVIC_IRQBASE], int_pend_src_i[NVIC_STNUM_NS],
		  int_pend_src_i[NVIC_PSVNUM_NS],
		  int_pend_src_i[NVIC_DMNUM:NVIC_SVCNUM_NS],
		  int_pend_src_i[NVIC_UFNUM_NS],
		  int_pend_src_i[NVIC_BFNUM:NVIC_MMNUM_NS],
		  int_pend_src_i[NVIC_HFNUM_NS], int_pend_src_i[NVIC_NMINUM]};
	end

	for (i = 0; (i < NUMIRQ); i = (i + 1)) begin : g_irq_pend_q 

	  if (IRQDIS[i] != 1'b1) begin : g_en_irq_pend_q 

	    assign irq_pend[i] = opt_irq_pend_q[i];
	  end
	  else  begin : g_no_irq_pend_q 

	    assign irq_pend[i] = 1'b0;
	  end
	end

	if (SECEXT != 0) begin : g_s_sync_pulse 

	  assign int_pend_pulse[(NUM_SYNC_EXCEP - 1):NVIC_PSVNUM_S] = 
		  int_pend_src_final[(NUM_SYNC_EXCEP - 1):NVIC_PSVNUM_S];
	  assign int_pend_pulse[NVIC_DMNUM] = (int_pend_src_final[NVIC_DMNUM] &
		  (~pend_state_masked[NVIC_DMNUM]));
	  assign int_pend_pulse[NVIC_SVCNUM_NS:NVIC_HFNUM_S] = 
		  int_pend_src_final[NVIC_SVCNUM_NS:NVIC_HFNUM_S];
	end
	else  begin : g_ns_sync_pulse 

	  assign int_pend_pulse[(NUM_SYNC_EXCEP - 1):7] = 
		  int_pend_src_final[(NUM_SYNC_EXCEP - 1):7];
	  assign int_pend_pulse[6] = (int_pend_src_final[6] &
		  (~pend_state_masked[6]));
	  assign int_pend_pulse[5:NVIC_HFNUM_S] = 
		  int_pend_src_final[5:NVIC_HFNUM_S];
	end

	for (j = 0; (j < NUMIRQ); j = (j + 1)) begin : g_int_state 

	  if (IRQDIS[j] != 1'b1) begin : g_en_int_state 

	    assign pend_state_masked[(j + NUM_SYNC_EXCEP)] = pend_state_q[(j +
		    NUM_SYNC_EXCEP)];
	    assign actv_state_masked[(j + NUM_SYNC_EXCEP)] = actv_state_q[(j +
		    NUM_SYNC_EXCEP)];
	  end
	  else  begin : g_no_int_state 

	    assign pend_state_masked[(j + NUM_SYNC_EXCEP)] = 1'b0;
	    assign actv_state_masked[(j + NUM_SYNC_EXCEP)] = 1'b0;
	  end
	end

	if (SECEXT != 0) begin : g_s_state 

	  if (NUMIRQ == IRQMAX) begin : g_s_max_state 

	    assign pend_state_nxt = masked_pend_state_nxt;
	    assign pend_state = pend_state_masked;
	    assign actv_state = actv_state_masked;
	  end
	  else  begin : g_s_pad_state 

	    assign pend_state_nxt = {{(IRQMAX - NUMIRQ) {1'b0}},
		    masked_pend_state_nxt};
	    assign pend_state = {{(IRQMAX - NUMIRQ) {1'b0}}, pend_state_masked};
	    assign actv_state = {{(IRQMAX - NUMIRQ) {1'b0}}, actv_state_masked};
	  end
	end
	else  begin : g_ns_state 

	  if (NUMIRQ == IRQMAX) begin : g_ns_max_state 

	    assign pend_state_nxt = {masked_pend_state_nxt[(NUM_PEND_ACTIVE -
		    1):NON_NUMIRQ_NS], masked_pend_state_nxt[8], 1'b0,
		    masked_pend_state_nxt[7], 1'b0, masked_pend_state_nxt[6],
		    masked_pend_state_nxt[5], 1'b0, 1'b0,
		    masked_pend_state_nxt[4], 1'b0, masked_pend_state_nxt[3],
		    masked_pend_state_nxt[2], 1'b0, masked_pend_state_nxt[1],
		    1'b0, masked_pend_state_nxt[0]};
	    assign pend_state = {pend_state_masked[(NUM_PEND_ACTIVE -
		    1):NON_NUMIRQ_NS], pend_state_masked[8], 1'b0,
		    pend_state_masked[7], 1'b0, pend_state_masked[6],
		    pend_state_masked[5], 1'b0, 1'b0, pend_state_masked[4],
		    1'b0, pend_state_masked[3], pend_state_masked[2], 1'b0,
		    pend_state_masked[1], 1'b0, pend_state_masked[0]};
	    assign actv_state = {actv_state_masked[(NUM_PEND_ACTIVE -
		    1):NON_NUMIRQ_NS], actv_state_masked[8], 1'b0,
		    actv_state_masked[7], 1'b0, actv_state_masked[6],
		    actv_state_masked[5], 1'b0, 1'b0, actv_state_masked[4],
		    1'b0, actv_state_masked[3], actv_state_masked[2], 1'b0,
		    actv_state_masked[1], 1'b0, actv_state_masked[0]};
	  end
	  else  begin : g_ns_pad_state 

	    assign pend_state_nxt = {{(IRQMAX - NUMIRQ) {1'b0}},
		    masked_pend_state_nxt[(NUM_PEND_ACTIVE - 1):NON_NUMIRQ_NS],
