	wire[(IRQLVL + 9):0]	regd_s_l5[((MAX_INTERRUPTS / 32) - 1):0];
	wire[(IRQLVL + 9):0]	regd_s_l6[((MAX_INTERRUPTS / 64) - 1):0];
	wire[(IRQLVL + 9):0]	regd_s_l7[((MAX_INTERRUPTS / 128) - 1):0];
	wire[(IRQLVL + 9):0]	regd_s_l8[((MAX_INTERRUPTS / 256) - 1):0];
	wire			neg_pri;
	wire			pos_pri;
	wire			unused_clk_rst_for_formal;
	wire			unused_pend_only_mask;
	wire			unused_regd_flop;
	genvar 			i;
	genvar 			x;
	genvar 			y;
	genvar 			z;
	wire[(IRQLVL + 10):0]	regd_l8_res[1:0];

	reg	[(IRQLVL + 10):0]
				regd_ns_l8_q[1:0];
	reg	[(IRQLVL + 10):0]
				regd_s_l8_q[1:0];
	genvar 			j;

	assign neg_pri = (|int_en_i[7:2]);
	assign pos_pri = (~neg_pri);
	assign comb_s_l0[0] = comb_s_l0_int[0];
	assign comb_s_l0[1] = {comb_s_l0_int[1][(IRQLVL + 9):9], 9'h003};
	assign comb_ns_l9 = f_cmp(comb_ns_l8[0], comb_ns_l8[1]);
	assign comb_s_l9 = f_cmp(comb_s_l8[0], comb_s_l8[1]);
	assign int_target_o = merge_final[(IRQLVL + 10)];
	assign int_valid_o = (~merge_final[(IRQLVL + 9)]);
	assign int_pri_o = merge_final[(IRQLVL + 8):9];
	assign int_num_o = merge_final[8:0];
	assign unused_clk_rst_for_formal = (|{fclk, reset_n});

	function automatic [(IRQLVL + 9):0] f_cmp;
	input logic
		[(IRQLVL + 9):0]
				left;
	input logic
		[(IRQLVL + 9):0]
				right;
	f_cmp = ((left[(IRQLVL + 9):9] > right[(IRQLVL + 9):9]) ? right : left);
	endfunction

	for (i = 0; (i < 16); i = (i + 1)) begin : g_sync_tree 

	  assign regd_ns_l0[i] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	  assign regd_s_l0[i] = {1'b1, {(IRQLVL + 9) {1'b0}}};

	  if (COMBIRQ[(i * 2)]) begin : g_comb_sync_s 

	    assign comb_s_l0_int[i] = {(~(int_en_i[(i * 2)] & (~int_target_i[(i
		    * 2)]))), int_pri_i[((IRQLVL * ((i * 2) + 1)) - 1):((IRQLVL
		    * i) * 2)], i[8:0]};
	  end
	  else  begin : g_no_comb_sync_s 

	    assign comb_s_l0_int[i] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	  end

	  if (COMBIRQ[((i * 2) + 1)]) begin : g_comb_sync_ns 

	    assign comb_ns_l0[i] = {(~(int_en_i[((i * 2) + 1)] &
		    int_target_i[((i * 2) + 1)])), int_pri_i[((IRQLVL * ((i * 2)
		    + 2)) - 1):(IRQLVL * ((i * 2) + 1))], i[8:0]};
	  end
	  else  begin : g_no_comb_sync_ns 

	    assign comb_ns_l0[i] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	  end
	end

	for (x = 2; (x < 16); x = (x + 1)) begin : g_sync_s_tree_align 

	  assign comb_s_l0[x] = comb_s_l0_int[x];
	end

	for (y = 16; (y < MAX_INTERRUPTS); y = (y + 1)) begin : g_irq_tree 

	  if (REGDIRQ[(y + 16)] && (y < IRQMAX_CORE)) begin : g_regd_irq_tree 

	    assign regd_ns_l0[y] = {(~(int_en_i[(y + 16)] & int_target_i[(y +
		    16)])), int_pri_i[((IRQLVL * (y + 17)) - 1):(IRQLVL * (y +
		    16))], y[8:0]};
	    assign regd_s_l0[y] = {(~(int_en_i[(y + 16)] & (~int_target_i[(y +
		    16)]))), int_pri_i[((IRQLVL * (y + 17)) - 1):(IRQLVL * (y +
		    16))], y[8:0]};
	  end
	  else  begin : g_no_regd_irq_tree 

	    assign regd_ns_l0[y] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	    assign regd_s_l0[y] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	  end

	  if (COMBIRQ[(y + 16)] && (y < IRQMAX_CORE)) begin : g_comb_irq_tree 

	    assign comb_ns_l0[y] = {(~(int_en_i[(y + 16)] & int_target_i[(y +
		    16)])), int_pri_i[((IRQLVL * (y + 17)) - 1):(IRQLVL * (y +
		    16))], y[8:0]};
	    assign comb_s_l0[y] = {(~(int_en_i[(y + 16)] & (~int_target_i[(y +
		    16)]))), int_pri_i[((IRQLVL * (y + 17)) - 1):(IRQLVL * (y +
		    16))], y[8:0]};
	  end
	  else  begin : g_no_comb_irq_tree 

	    assign comb_ns_l0[y] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	    assign comb_s_l0[y] = {1'b1, {(IRQLVL + 9) {1'b0}}};
	  end
	end

	for (z = 0; (z < (MAX_INTERRUPTS / 2)); z = (z + 1)) begin : 
		g_compare_tree 

	  if (z < 256) begin : g_l1 

	    assign regd_ns_l1[z] = f_cmp(regd_ns_l0[(2 * z)], regd_ns_l0[((2 *
		    z) + 1)]);
	    assign regd_s_l1[z] = f_cmp(regd_s_l0[(2 * z)], regd_s_l0[((2 * z) +
		    1)]);
	    assign comb_ns_l1[z] = f_cmp(comb_ns_l0[(2 * z)], comb_ns_l0[((2 *
		    z) + 1)]);
	    assign comb_s_l1[z] = f_cmp(comb_s_l0[(2 * z)], comb_s_l0[((2 * z) +
		    1)]);
	  end

	  if (z < 128) begin : g_l2 

	    assign regd_ns_l2[z] = f_cmp(regd_ns_l1[(2 * z)], regd_ns_l1[((2 *
		    z) + 1)]);
	    assign regd_s_l2[z] = f_cmp(regd_s_l1[(2 * z)], regd_s_l1[((2 * z) +
		    1)]);
	    assign comb_ns_l2[z] = f_cmp(comb_ns_l1[(2 * z)], comb_ns_l1[((2 *
		    z) + 1)]);
	    assign comb_s_l2[z] = f_cmp(comb_s_l1[(2 * z)], comb_s_l1[((2 * z) +
		    1)]);
	  end

	  if (z < 64) begin : g_l3 

	    assign regd_ns_l3[z] = f_cmp(regd_ns_l2[(2 * z)], regd_ns_l2[((2 *
		    z) + 1)]);
	    assign regd_s_l3[z] = f_cmp(regd_s_l2[(2 * z)], regd_s_l2[((2 * z) +
		    1)]);
	    assign comb_ns_l3[z] = f_cmp(comb_ns_l2[(2 * z)], comb_ns_l2[((2 *
		    z) + 1)]);
	    assign comb_s_l3[z] = f_cmp(comb_s_l2[(2 * z)], comb_s_l2[((2 * z) +
		    1)]);
	  end

	  if (z < 32) begin : g_l4 

	    assign regd_ns_l4[z] = f_cmp(regd_ns_l3[(2 * z)], regd_ns_l3[((2 *
		    z) + 1)]);
	    assign regd_s_l4[z] = f_cmp(regd_s_l3[(2 * z)], regd_s_l3[((2 * z) +
		    1)]);
	    assign comb_s_l4[z] = f_cmp(comb_s_l3[(2 * z)], comb_s_l3[((2 * z) +
		    1)]);
	    assign comb_ns_l4[z] = f_cmp(comb_ns_l3[(2 * z)], comb_ns_l3[((2 *
		    z) + 1)]);
	  end

	  if (z < 16) begin : g_l5 

	    if (z == 0) begin : g_l5_sync 

	      assign comb_s_l5[z] = ((PEND != 0) ? f_cmp(comb_s_l4[(2 * z)],
		      {(comb_s_l4[((2 * z) + 1)][(IRQLVL + 9)] |
		      dbg_mask_ints_s_i), comb_s_l4[((2 * z) + 1)][(IRQLVL +
		      8):0]}) : f_cmp(comb_s_l4[(2 * z)], comb_s_l4[((2 * z) +
		      1)]));
	      assign comb_ns_l5[z] = ((PEND != 0) ? f_cmp(comb_ns_l4[(2 * z)],
		      {(comb_ns_l4[((2 * z) + 1)][(IRQLVL + 9)] |
		      dbg_mask_ints_ns_i), comb_ns_l4[((2 * z) + 1)][(IRQLVL +
		      8):0]}) : f_cmp(comb_ns_l4[(2 * z)], comb_ns_l4[((2 * z) +
		      1)]));
	      assign regd_s_l5[z] = ((PEND != 0) ? f_cmp(regd_s_l4[(2 * z)],
		      {(regd_s_l4[((2 * z) + 1)][(IRQLVL + 9)] |
		      dbg_mask_ints_s_i), regd_s_l4[((2 * z) + 1)][(IRQLVL +
		      8):0]}) : f_cmp(regd_s_l4[(2 * z)], regd_s_l4[((2 * z) +
		      1)]));
	      assign regd_ns_l5[z] = ((PEND != 0) ? f_cmp(regd_ns_l4[(2 * z)],
		      {(regd_ns_l4[((2 * z) + 1)][(IRQLVL + 9)] |
		      dbg_mask_ints_ns_i), regd_ns_l4[((2 * z) + 1)][(IRQLVL +
		      8):0]}) : f_cmp(regd_ns_l4[(2 * z)], regd_ns_l4[((2 * z) +
		      1)]));
	    end
	    else  begin : g_l5_non_sync 

	      assign comb_s_l5[z] = ((PEND != 0) ? f_cmp({(comb_s_l4[(2 *
		      z)][(IRQLVL + 9)] | dbg_mask_ints_s_i), comb_s_l4[(2 *
		      z)][(IRQLVL + 8):0]}, {(comb_s_l4[((2 * z) + 1)][(IRQLVL +
		      9)] | dbg_mask_ints_s_i), comb_s_l4[((2 * z) + 1)][(IRQLVL
		      + 8):0]}) : f_cmp(comb_s_l4[(2 * z)], comb_s_l4[((2 * z) +
		      1)]));
	      assign comb_ns_l5[z] = ((PEND != 0) ? f_cmp({(comb_ns_l4[(2 *
		      z)][(IRQLVL + 9)] | dbg_mask_ints_ns_i), comb_ns_l4[(2 *
		      z)][(IRQLVL + 8):0]}, {(comb_ns_l4[((2 * z) + 1)][(IRQLVL
		      + 9)] | dbg_mask_ints_ns_i), comb_ns_l4[((2 * z) +
		      1)][(IRQLVL + 8):0]}) : f_cmp(comb_ns_l4[(2 * z)],
		      comb_ns_l4[((2 * z) + 1)]));
	      assign regd_s_l5[z] = ((PEND != 0) ? f_cmp({(regd_s_l4[(2 *
		      z)][(IRQLVL + 9)] | dbg_mask_ints_s_i), regd_s_l4[(2 *
		      z)][(IRQLVL + 8):0]}, {(regd_s_l4[((2 * z) + 1)][(IRQLVL +
		      9)] | dbg_mask_ints_s_i), regd_s_l4[((2 * z) + 1)][(IRQLVL
		      + 8):0]}) : f_cmp(regd_s_l4[(2 * z)], regd_s_l4[((2 * z) +
		      1)]));
	      assign regd_ns_l5[z] = ((PEND != 0) ? f_cmp({(regd_ns_l4[(2 *
		      z)][(IRQLVL + 9)] | dbg_mask_ints_ns_i), regd_ns_l4[(2 *
		      z)][(IRQLVL + 8):0]}, {(regd_ns_l4[((2 * z) + 1)][(IRQLVL
		      + 9)] | dbg_mask_ints_ns_i), regd_ns_l4[((2 * z) +
		      1)][(IRQLVL + 8):0]}) : f_cmp(regd_ns_l4[(2 * z)],
		      regd_ns_l4[((2 * z) + 1)]));
	    end
	  end

	  if (z < 8) begin : g_l6 

	    assign regd_ns_l6[z] = f_cmp(regd_ns_l5[(2 * z)], regd_ns_l5[((2 *
		    z) + 1)]);
	    assign regd_s_l6[z] = f_cmp(regd_s_l5[(2 * z)], regd_s_l5[((2 * z) +
		    1)]);
	    assign comb_ns_l6[z] = f_cmp(comb_ns_l5[(2 * z)], comb_ns_l5[((2 *
		    z) + 1)]);
	    assign comb_s_l6[z] = f_cmp(comb_s_l5[(2 * z)], comb_s_l5[((2 * z) +
		    1)]);
	  end

	  if (z < 4) begin : g_l7 

	    assign regd_ns_l7[z] = f_cmp(regd_ns_l6[(2 * z)], regd_ns_l6[((2 *
		    z) + 1)]);
	    assign regd_s_l7[z] = f_cmp(regd_s_l6[(2 * z)], regd_s_l6[((2 * z) +
		    1)]);
	    assign comb_ns_l7[z] = f_cmp(comb_ns_l6[(2 * z)], comb_ns_l6[((2 *
		    z) + 1)]);
	    assign comb_s_l7[z] = f_cmp(comb_s_l6[(2 * z)], comb_s_l6[((2 * z) +
		    1)]);
	  end

	  if (z < 2) begin : g_l8 

	    assign regd_ns_l8[z] = f_cmp(regd_ns_l7[(2 * z)], regd_ns_l7[((2 *
		    z) + 1)]);
	    assign regd_s_l8[z] = f_cmp(regd_s_l7[(2 * z)], regd_s_l7[((2 * z) +
		    1)]);
	    assign comb_ns_l8[z] = f_cmp(comb_ns_l7[(2 * z)], comb_ns_l7[((2 *
		    z) + 1)]);
	    assign comb_s_l8[z] = f_cmp(comb_s_l7[(2 * z)], comb_s_l7[((2 * z) +
		    1)]);
	  end
	end

	for (j = 0; (j < 2); j = (j + 1)) begin : g_regd_l8 

	  assign regd_ns_l8_q[j][8] = j[0];
	  assign regd_s_l8_q[j][8] = j[0];
	  assign regd_ns_l8_q[j][(IRQLVL + 10)] = 1'b1;
	  assign regd_s_l8_q[j][(IRQLVL + 10)] = 1'b0;

	  if (REGD_SLICE[((256 * (j + 1)) - 1):(256 * j)] != 256'b0) begin : 
		  g_regd_merge_l8 
	    yamin_nvic_merge #(.IRQLVL(IRQLVL), .PEND(PEND), .FULL(0), .FINALS(
		    0)) u_yamin_nvic_merge_regd(
		.pri_one_i			(regd_ns_l8_q[j]), 
		.pri_two_i			(regd_s_l8_q[j]), 
		.pos_pri_one_i			(1'b1), 
		.aircr_pris_i			(aircr_pris_i), 
		.pre_emptive_mask_ns_i		(pre_emptive_mask_ns_i), 
		.pre_emptive_mask_s_i		(pre_emptive_mask_s_i), 
		.merge_o			(regd_l8_res[j]));

	    always_ff @(posedge fclk or negedge reset_n) if (~reset_n) begin
	      regd_ns_l8_q[j][(IRQLVL + 9)] <= 1'b1;
	      regd_ns_l8_q[j][(IRQLVL + 8):9] <= {IRQLVL {1'b0}};
	      regd_ns_l8_q[j][7:0] <= 8'b0;
	      regd_s_l8_q[j][(IRQLVL + 9)] <= 1'b1;
	      regd_s_l8_q[j][(IRQLVL + 8):9] <= {IRQLVL {1'b0}};
	      regd_s_l8_q[j][7:0] <= 8'b0;
	    end
	    else
	      begin
		regd_ns_l8_q[j][(IRQLVL + 9)] <= regd_ns_l8[j][(IRQLVL + 9)];
		regd_ns_l8_q[j][(IRQLVL + 8):9] <= regd_ns_l8[j][(IRQLVL + 8):9]
			;
		regd_ns_l8_q[j][7:0] <= regd_ns_l8[j][7:0];
		regd_s_l8_q[j][(IRQLVL + 9)] <= regd_s_l8[j][(IRQLVL + 9)];
		regd_s_l8_q[j][(IRQLVL + 8):9] <= regd_s_l8[j][(IRQLVL + 8):9];
		regd_s_l8_q[j][7:0] <= regd_s_l8[j][7:0];
	      end
	  end
	  else  begin : g_no_regd_merge_l8 

	    assign {regd_ns_l8_q[j][(IRQLVL + 9)], regd_ns_l8_q[j][(IRQLVL +
		    8):9], regd_ns_l8_q[j][7:0]} = {1'b1, {(IRQLVL + 8) {1'b0}}}
		    ;
	    assign {regd_s_l8_q[j][(IRQLVL + 9)], regd_s_l8_q[j][(IRQLVL +
		    8):9], regd_s_l8_q[j][7:0]} = {1'b1, {(IRQLVL + 8) {1'b0}}};
	    assign regd_l8_res[j] = {1'b0, 1'b1, {(IRQLVL + 9) {1'b0}}};
	  end
	end

	if (REGD_SLICE != 512'b0) begin : g_l9_regd_merge 
	  yamin_nvic_merge #(.IRQLVL(IRQLVL), .PEND(PEND), .FULL(0), .FINALS(0))
		  u_yamin_nvic_merge_comb(
		.pri_one_i			({1'b1, comb_ns_l9}), 
		.pri_two_i			({1'b0, comb_s_l9}), 
		.pos_pri_one_i			(1'b1), 
		.aircr_pris_i			(aircr_pris_i), 
		.pre_emptive_mask_ns_i		(pre_emptive_mask_ns_i), 
		.pre_emptive_mask_s_i		(pre_emptive_mask_s_i), 
		.merge_o			(comb_l9_merge));

	  wire	[(IRQLVL + 10):0]
				regd_l9_merge;
	  yamin_nvic_merge #(.IRQLVL(IRQLVL), .PEND(PEND), .FULL(1), .FINALS(0))
		  u_yamin_nvic_merge_reg_final(
		.pri_one_i			(regd_l8_res[1]), 
		.pri_two_i			(regd_l8_res[0]), 
		.pos_pri_one_i			(1'b1), 
		.aircr_pris_i			(aircr_pris_i), 
		.pre_emptive_mask_ns_i		(pre_emptive_mask_ns_i), 
		.pre_emptive_mask_s_i		(pre_emptive_mask_s_i), 
		.merge_o			(regd_l9_merge));
	  wire			dbg_mask_ints;
	  wire	[(IRQLVL + 10):0]
				regd_l9_masked;
	  wire	[(IRQLVL + 10):0]
				regd_nmi_hf;
	  yamin_nvic_merge #(.IRQLVL(IRQLVL), .PEND(PEND), .FULL(1), .FINALS(1))
		  u_yamin_nvic_merge_final(
		.pri_one_i			(regd_nmi_hf), 
		.pri_two_i			(comb_l9_merge), 
		.pos_pri_one_i			(pos_pri), 
		.aircr_pris_i			(aircr_pris_i), 
		.pre_emptive_mask_ns_i		(pre_emptive_mask_ns_i), 
		.pre_emptive_mask_s_i		(pre_emptive_mask_s_i), 
		.merge_o			(merge_final));

	  assign dbg_mask_ints = ((PEND != 0) ? (((~regd_l9_merge[(IRQLVL +
		  10)]) & dbg_mask_ints_s_i) | (regd_l9_merge[(IRQLVL + 10)] &
		  dbg_mask_ints_ns_i)) : 1'b0);
	  assign regd_l9_masked = {regd_l9_merge[(IRQLVL + 10)],
		  (regd_l9_merge[(IRQLVL + 9)] | dbg_mask_ints),
		  regd_l9_merge[(IRQLVL + 8):0]};
	  assign regd_nmi_hf = (int_en_i[2] ? {int_target_i[2], 1'b0, {IRQLVL
		  {1'b0}}, 9'h003} : ((|int_en_i[5:4]) ? {((int_target_i[5] &
		  int_en_i[5]) & (~int_en_i[4])), 1'b0, {IRQLVL {1'b0}}, 9'h002}
		  : ((|int_en_i[7:6]) ? {((int_target_i[7] & int_en_i[7]) &
		  (~int_en_i[6])), 1'b0, {IRQLVL {1'b0}}, 9'h003} :
		  regd_l9_masked)));
	end
	else  begin : g_l9_no_regd_merge 

	  wire	[(IRQLVL + 10):0]
				nmi_hf;
	  yamin_nvic_merge #(.IRQLVL(IRQLVL), .PEND(PEND), .FULL(0), .FINALS(1))
		  u_yamin_nvic_merge_comb_only(
		.pri_one_i			({1'b1, comb_ns_l9}), 
		.pri_two_i			({1'b0, comb_s_l9}), 
		.pos_pri_one_i			(1'b1), 
		.aircr_pris_i			(aircr_pris_i), 
		.pre_emptive_mask_ns_i		(pre_emptive_mask_ns_i), 
		.pre_emptive_mask_s_i		(pre_emptive_mask_s_i), 
		.merge_o			(comb_l9_merge));

	  assign nmi_hf = (int_en_i[2] ? {int_target_i[2], 1'b0, {IRQLVL
		  {1'b0}}, 9'h003} : ((|int_en_i[5:4]) ? {((int_target_i[5] &
		  int_en_i[5]) & (~int_en_i[4])), 1'b0, {IRQLVL {1'b0}}, 9'h002}
		  : {((int_target_i[7] & int_en_i[7]) & (~int_en_i[6])), 1'b0,
		  {IRQLVL {1'b0}}, 9'h003}));
	  assign merge_final = ((nmi_hf & {(IRQLVL + 11) {neg_pri}}) |
		  (comb_l9_merge & {(IRQLVL + 11) {pos_pri}}));
	end

	if (PEND) begin : g_pend_mask 

	  assign unused_pend_only_mask = '0;
	end
	else  begin : g_no_pend_mask 

	  assign unused_pend_only_mask = (|{dbg_mask_ints_ns_i,
		  dbg_mask_ints_s_i});
	end

	if (REGD_SLICE != 512'b0) begin : g_regd_unused 

	  assign unused_regd_flop = '0;
	end
	else  begin : g_no_regd_unused 

	  assign unused_regd_flop = (|{regd_ns_l8_q[1], regd_ns_l8_q[0],
		  regd_s_l8_q[1], regd_s_l8_q[0], regd_ns_l8[1], regd_ns_l8[0],
		  regd_s_l8[1], regd_s_l8[0], regd_l8_res[1], regd_l8_res[0]});
