	function automatic [2:0] add_ptr;
	input logic
		[2:0]		in_ptr;
	input logic
		[2:0]		addend;

	logic	[3:0]		add_ptr_full;
	logic	[3:0]		add_ptr_wrap_full;
	logic			unused;
	begin
	  add_ptr_full = ({1'b0, in_ptr} + {1'b0, addend});
	  add_ptr_wrap_full = ((add_ptr_full >= {1'b0, BUFFER_MAX}) ?
		  (add_ptr_full - {1'b0, BUFFER_MAX}) : add_ptr_full);
	  add_ptr = add_ptr_wrap_full[2:0];
	  unused = add_ptr_wrap_full[3];
	end
	endfunction

	function automatic [2:0] earliest_ptr;
	input logic
		[(BUFFER_MAX - 1):0]
				valids;
	input logic
		[2:0]		front_ptr;

	logic			seen;
	logic	[2:0]		tmp_ptr;
	logic	[2:0]		addend;
	begin
	  seen = 1'b0;
	  tmp_ptr = 3'b0;
	  earliest_ptr = {3 {1'b0}};
	  begin

	    int			i;
	    for (i = 0; (i < int'(BUFFER_MAX)); i = (i + 1)) begin
	      addend = i[2:0];
	      tmp_ptr = add_ptr(front_ptr, addend);
	      if ((~seen) & valids[tmp_ptr]) begin
		seen = 1'b1;
		earliest_ptr = tmp_ptr;
	      end
	    end
	  end
	end
	endfunction

